class MaterialNomiBand(ValueError):
    """kech142 (zip 170, A-O09): yaratilayotgan material nomi shu korxonada band — marshrut 409. `detail` — sahifa uchun
    (JSON): `type` («material_nomi_band» — faol material, «material_nomi_yashirin» — o'chirilgan (yashirilgan) material
    boshqa birlik / turda), `message`, faol material uchun `id`, `item_name`, `unit`, `is_penoplast` — Kirim /
    Ta'minotchilar sahifasi mavjud materialni ro'yxatdan o'zi tanlaydi."""

    def __init__(self, detail: dict):
        super().__init__(str((detail or {}).get("message") or "Material nomi band"))
        self.detail = dict(detail or {})


def material_nomi_band_detail(m) -> dict:
    """kech142 (zip 170, A-O09): faol material nomi band bo'lganda 409 javobi (yaratish va parallel yaratish — bitta matn)."""
    return {
        "type": "material_nomi_band",
        "message": (f"«{m.item_name}» nomli material omborda allaqachon bor (birligi: {m.unit or '—'}) — "
                    f"ro'yxatdan tanlang"),
        "id": m.id,
        "item_name": m.item_name,
        "unit": m.unit,
        "is_penoplast": bool(m.is_penoplast),
    }


# kech143 (zip 171, jonli topilma N1 — 12.10 22:1x staging, O'LCHANGAN `work/audit/tasdiq/himoya/p_himoya.py` N1a–f, SQLite = PG):
# material nomi taqqoslanishi AYNAN tenglik edi — «N1 Oq Mel», «n1 oq mel» (boshqa birlikda), «N1  Oq   Mel», «Bo'yoq» / «Boʻyoq»,
# kirill «МЕЛ» / «мел» — har biri ALOHIDA material bo'lib yaratilar, boshqa material nomiga harf farqi bilan qayta nomlash ham
# o'tardi (ombor, retsept, kirimda ikki «bir xil» material). Endi nom KALITI bilan: bo'shliqlar bittaga, apostrof turlari
# (‘ ’ ʻ ʼ ` ´) bitta «'», harf katta-kichikligi farqsiz (`casefold` — kirill ham; SQLite `lower()` faqat lotin — shuning uchun
# Python da). Bazadagi eski takrorlar (bo'lsa) o'zgartirilmaydi — yangi yaratish / qayta nomlash ularga ham uriladi.
_APOSTROF_TURLARI = "\u2018\u2019\u02bb\u02bc`\u00b4"
MATERIAL_NOMI_QULF_NS = 171        # `_pul_qulfi` fazosi: korxona bo'yicha material nomi (PG — bir vaqtda «Akril» va «akril»)


def material_nomi_kaliti(nom) -> str:
    """Material nomining taqqoslash kaliti (yuqoridagi qoida)."""
    s = str(nom or "")
    for ch in _APOSTROF_TURLARI:
        s = s.replace(ch, "'")
    return " ".join(s.split()).casefold()


# kech159 (zip 219 — egasi tanlovi 27.10 «Kichik qoldiqlar (Tavsiya)»; O'LCHANGAN `work/k219/probe219.py`, SQLite = PG): «Tayyor loy (…)» —
# dastur o'zi yaratadigan ortgan loy zaxirasi (`services.get_or_create_loy_stock`: `f"Tayyor loy ({retsept})"`), hamma joyda shu NOM
# bilan taniladi (kam qoldiq, Omborxona, hisobotlar). Ilgari oddiy material shu nomni olishi mumkin edi — «qop» material loy zaxirasi
# bo'lib, kg loy qo'shilib ketdi, «kam qoldi» ogohlantirishi yo'qoldi. Endi nom KALITI shu bilan boshlansa — band (yaratish / qayta
# nomlash 400); mavjud retseptning zaxirasi — nomi, birligi, turi o'zgarmaydi; retsept nomi o'zgarsa zaxira ham o'tadi.
LOY_ZAXIRA_PREFIKS = "Tayyor loy ("                         # = `services.TAYYOR_LOY_PREFIKS` (test T1 tengligini tekshiradi)
# «Tayyor loy (<retsept>)» `inventory.item_name` (VARCHAR(100)) ga sig'sin: 100 − 12 − 1 = 87 (ilgari 88+ belgili retsept PG da 500 berardi)
RETSEPT_NOMI_MAX = 100 - len(LOY_ZAXIRA_PREFIKS) - len(")")
LOY_ZAXIRA_NOMI_XATO = ("«Tayyor loy (…)» bilan boshlanadigan nom ortgan loy zaxirasi uchun band — dastur uni retsept nomi bilan o'zi "
                        "yaratadi. Materialga boshqa nom bering")


_KORINMAS219 = dict.fromkeys(map(ord, "\u200b\u200c\u200d\u2060\ufeff\u00ad"))      # ko'rinmas belgilar (review219 №9)


def loy_zaxira_nomimi(nom) -> bool:
    """kech159 (zip 219): nom (KALITI — harf / bo'shliq / apostrof farqsiz, ko'rinmas belgilarsiz) «Tayyor loy (» bilan boshlanadimi."""
    return material_nomi_kaliti(str(nom or "").translate(_KORINMAS219)).startswith(material_nomi_kaliti(LOY_ZAXIRA_PREFIKS))


def loy_zaxirasi_retsepti(db: Session, item):
    """kech159 (zip 219): material shu korxonadagi MAVJUD retseptning ortgan loy zaxirasimi (nomi AYNAN «Tayyor loy (<retsept nomi>)» —
    `services.get_or_create_loy_stock` shu nom bilan topadi; birligi kg, oddiy material — zaxira shakli) — o'sha retsept, aks holda None.
    review219 №4: shakli boshqa (masalan «qop») eski qator — zaxira emas (prefiksiz nomga qayta nomlab tuzatib olish mumkin)."""
    from models import Recipe as _Rec219
    nom = str(getattr(item, "item_name", "") or "")
    if not (nom.startswith(LOY_ZAXIRA_PREFIKS) and nom.endswith(")")):
        return None
    if str(getattr(item, "unit", "") or "").strip().casefold() != "kg" or getattr(item, "is_penoplast", False):
        return None
    q = db.query(_Rec219).filter(_Rec219.name == nom[len(LOY_ZAXIRA_PREFIKS):-1])
    if getattr(item, "company_id", None) is not None:
        q = q.filter(_Rec219.company_id == item.company_id)
    return q.order_by(_Rec219.id).first()


def retsept_nomi_uzunlik_xatosi(nom):
    """kech159 (zip 219, L7): retsept nomi `RETSEPT_NOMI_MAX` dan uzun bo'lsa — xato matni, aks holda None."""
    n = len(str(nom or "").strip())
    if n > RETSEPT_NOMI_MAX:
        return (f"Retsept nomi juda uzun ({n} belgi) — ko'pi bilan {RETSEPT_NOMI_MAX} belgi yozing (ombordagi «Tayyor loy (…)» zaxira "
                f"nomi shundan tuziladi)")
    return None


def retsept_loy_zaxirasi(db: Session, recipe, nom=None, qulf: bool = False):
    """kech159 (zip 219): retseptning ortgan loy zaxirasi (`nom` — boshqa nom bilan; berilmasa retseptning joriy nomi) yoki None.
    `qulf` — qator `FOR UPDATE` (qayta nomlash)."""
    _rn = nom if nom is not None else (recipe.name.value if hasattr(recipe.name, 'value') else str(recipe.name or ""))
    q = db.query(Inventory).filter(Inventory.item_name == f"{LOY_ZAXIRA_PREFIKS}{_rn})")
    if getattr(recipe, "company_id", None) is not None:
        q = q.filter(Inventory.company_id == recipe.company_id)
    q = q.order_by(Inventory.id)
    return inventory_qulf_sorov(db, q) if qulf else q.first()


def retsept_zaxira_nomi_xatosi(db: Session, recipe, yangi_nom):
    """kech159 (zip 219, L6): retsept `yangi_nom` ga o'zgartirilsa uning ortgan loy zaxirasi «Tayyor loy (<yangi>)» ga o'tadi — shu nom
    (KALITI) omborda BOSHQA materialda (yashiringani ham) band bo'lsa xato matni (409), aks holda None. Zaxirasi yo'q retsept — None."""
    _eski = recipe.name.value if hasattr(recipe.name, 'value') else str(recipe.name or "")
    _yangi = str(yangi_nom or "").strip()
    if _yangi == _eski:
        return None
    _zx = retsept_loy_zaxirasi(db, recipe)
    if _zx is None:
        return None
    _band = next(iter(nomdosh_materiallar(db, recipe.company_id, f"{LOY_ZAXIRA_PREFIKS}{_yangi})", istisno_id=_zx.id)), None)
    if _band is None:
        return None
    if _band.is_deleted:      # review219 №7: yashirin material Omborxonada ko'rinmaydi va o'chirib bo'lmaydi — faqat boshqa nom
        return (f"«{_band.item_name}» nomi avval o'chirilgan (yashirilgan) materialda band — «{_zx.item_name}» ortgan loy zaxirasi yangi "
                f"nomga o'tolmaydi. Retseptga boshqa nom bering")
    return (f"Omborda «{_band.item_name}» nomli material bor — «{_zx.item_name}» ortgan loy zaxirasi yangi nomga o'tolmaydi. Retseptga "
            f"boshqa nom bering (yoki o'sha materialni Omborxonada boshqa nomga o'zgartiring)")


def nomdosh_materiallar(db: Session, company_id, nom, istisno_id: int = None) -> list:
    """Shu korxonadagi nom KALITI mos materiallar (faol va yashirin) — id tartibida, AYNAN nomlisi birinchi."""
    kalit = material_nomi_kaliti(nom)
    q = db.query(Inventory.id, Inventory.item_name)
    if company_id is not None:
        q = q.filter(Inventory.company_id == company_id)
    if istisno_id is not None:
        q = q.filter(Inventory.id != istisno_id)
    idlar = [i for i, n in q.order_by(Inventory.id).all() if material_nomi_kaliti(n) == kalit]
    if not idlar:
        return []
    _toza = str(nom or "").strip()
    q2 = db.query(Inventory).filter(Inventory.id.in_(idlar))
    if company_id is not None:
        q2 = q2.filter(Inventory.company_id == company_id)
    qatorlar = {m.id: m for m in q2.all()}
    return sorted((qatorlar[i] for i in idlar if i in qatorlar), key=lambda m: (m.item_name != _toza, m.id))


def _birlik_ogirish_xatosi(unit, base_unit, conversion_factor):
    """kech142 (zip 170, A-O10 c — O'LCHANGAN kodda): materialning «mayda birligi» (`base_unit`, masalan «g») ombor birligidan
    (`unit`, masalan «qop») farq qilsa — o'girish koeffitsienti (`conversion_factor` > 0, 1 qop necha g) MAJBURIY.
    Ilgari koeffitsientsiz ham saqlanardi: retseptda «500 g» ko'rinardi, ishlab chiqarish esa 500 QOP yechib, 500 qop
    narxini tannarxga yozardi (`production_service._compute_bom_line` faqat ikkalasi bo'lsa o'giradi). Yaratish va
    tahrirda NATIJAVIY holat tekshiriladi (koeffitsient o'chirilib, mayda birlik qolsa ham). Xato — matn, aks holda None."""
    bu = str(base_unit).strip() if base_unit is not None else ""
    if not bu or bu == str(unit or "").strip():
        return None
    try:
        f = float(conversion_factor) if conversion_factor is not None else 0.0
    except (TypeError, ValueError):
        f = 0.0
    if not (f > 0):
        return (f"«{bu}» mayda birligi uchun o'girish koeffitsienti kerak (1 {str(unit or '').strip() or 'birlik'} "
                f"necha {bu}) — usiz retseptdagi miqdor ombor birligida yechilib ketadi")
    return None


def add_item(db: Session, item_data: InventoryCreate, company_id: int = None, performed_by: str = None) -> Inventory:
    """Yangi xomashyo qo'shadi.

    2026-09-18 — M8/F1: `company_id` ANIQ beriladi. Ilgari endpoint uni
    `add_item()` QAYTGANIDAN KEYIN qo'yardi, ya'ni funksiya ichidagi
    `db.commit()` vaqtida ustun bo'sh bo'lar va faqat bazadagi vaqtinchalik
    `DEFAULT 1` uni to'ldirardi. Default olib tashlangach bu yo'l
    NOT NULL xatosi berardi — shuning uchun tenant endi boshidanoq
    beriladi. "Tiriltirish" (o'chirilgan qatorni qayta ishlatish) mantig'i
    ham SHU korxona ichida qidiradi.

    kech142 (zip 170, A-O09 — O'LCHANGAN `work/audit/tasdiq/ombor/p_o09.py`, SQLite = PG; egasi qarori 12.10 «O'chirishdan
    oldin 0 bo'lsin» bilan birga):
      * Shu nomli FAOL material bor — `MaterialNomiBand` (409, mavjud material id si bilan), HECH NARSA yozilmaydi.
        Ilgari qoldig'i 0 va xaridsiz faol material jimgina QAYTA YOZILARDI: birligi, penoplast belgisi, hatto
        korxonaning ASOSIY penoplasti belgisi, blok hajmi (yuborilmasa ham 1.0), minimal qoldiq — retseptda / harakatlarda
        ishlatilgan bo'lsa ham («O9 Akril» kg → litr, asosiy penoplast; boshqa foydalanuvchining «Lenta» si almashdi).
      * O'chirilgan (yashirilgan) material — boshqa birlik yoki tur bilan — 409 («material_nomi_yashirin»); AYNAN shu
        birlik va turda — o'sha material TIKLANADI: eski qoldiq SAQLANADI, yangi miqdor QO'SHILADI (harakat bilan —
        hech narsa jim yo'qolmaydi; ilgari qoldiq ustidan yozilardi: 30 kg + 5 → 5 kg, harakat yo'q), narx / hajm —
        kirim qoidasi bilan (eski qoldiq musbat bo'lsa o'rtacha, aks holda yangi), boshqa maydonlar — faqat
        yuborilganlari.
    kech142 (zip 170, A-O05 d): boshlang'ich qoldiq ombor HARAKATI bilan («Boshlang'ich qoldiq …»; ilgari qoldiq 50,
    harakatlar yig'indisi 0 — «Harakatlar tarixi» qoldiqqa mos kelmasdi). Material, harakat, xarid va asosiy penoplast
    belgisi — BITTA tranzaksiyada (ilgari 2–3 commit). Mayda birlik — koeffitsient bilan (`_birlik_ogirish_xatosi`)."""
    from models import InventoryPurchase
    # 15-band: qat'iy tekshiruv — HECH NARSA yozilmasdan OLDIN (ValueError → 400).
    _clean_create("Inventory", item_data.model_dump(exclude_unset=True))
    # kech112 (K112-4): nom chetidagi bo'shliqlarsiz (" Akril " va "Akril" — bitta material; UI ham `trim` qiladi,
    # API esa bo'shliqli nomni ALOHIDA material qilib yaratardi — O'LCHANGAN `work/k113/probe_nom.py`). Bo'shliqsiz
    # uzunlik (kamida 2) yuqoridagi `_clean_create` da tekshirilgan.
    _toza_nom = str(item_data.item_name or "").strip()
    if _toza_nom != item_data.item_name:
        item_data = item_data.model_copy(update={"item_name": _toza_nom})
    # kech159 (zip 219, L1 / L2): «Tayyor loy (…)» — ortgan loy zaxirasiga band (dastur o'zi yaratadi), hech narsa yozilmaydi
    if loy_zaxira_nomimi(_toza_nom):
        raise ValueError(LOY_ZAXIRA_NOMI_XATO)
    is_peno = getattr(item_data, 'is_penoplast', False)
    # kech105 (K105-3, O'LCHANGAN — work/probe105.py): turkum ANIQ "Penoplast", `is_penoplast` esa umuman
    # YUBORILMAGAN bo'lsa (Ta'minotchilar sahifasi shunday yuborardi) — bu penoplast (plotnost). Ilgari
    # oddiy material bo'lib qolardi: buyurtma plotnost tanlovida yo'q, blok hajmi so'ralmasdi. ANIQ
    # yuborilgan `is_penoplast` (true / false) — o'zgarishsiz.
    _yuborilgan = set(getattr(item_data, 'model_fields_set', set()) or set())
    if (not is_peno and str(getattr(item_data, 'category', None) or '').strip() == 'Penoplast'
            and 'is_penoplast' not in _yuborilgan):
        is_peno = True
    is_default = getattr(item_data, 'is_default_penoplast', False)

    # Nom korxona ichida YAGONA (`uq_inventory_company_item_name` — yashirilgan qator ham nomni band qiladi).
    _scope = (lambda q: q.filter(Inventory.company_id == company_id)) if company_id is not None else (lambda q: q)

    # kech143 (zip 171, N1): nom KALITI bo'yicha (`nomdosh_materiallar`; harf / bo'shliq / apostrof farqi — bitta nom), PG da
    # korxona bo'yicha qulf ostida (tekshiruv va yozish orasida boshqa so'rov «akril» ni yarata olmaydi).
    _pul_qulfi(db, MATERIAL_NOMI_QULF_NS, company_id or 0)
    _nomdosh = nomdosh_materiallar(db, company_id, item_data.item_name)
    # kech142 (zip 170, A-O09): FAOL material — qayta yozilmaydi (409, sahifa uni ro'yxatdan tanlaydi). `isnot(True)` —
    # eski NULL qatorlar ham ko'rinadigan material hisoblanadi (boshqa joylardagidek).
    _faol = next((m for m in _nomdosh if m.is_deleted is not True), None)
    if _faol is not None:
        raise MaterialNomiBand(material_nomi_band_detail(_faol))
    _yashirin = [m for m in _nomdosh if m.is_deleted is True]
    # Yashirin nomdoshlardan — AYNAN shu birlik va turdagisi tiklanadi (aynan nomlisi birinchi); mosi yo'q bo'lsa — birinchisi
    # (quyida 409 «material_nomi_yashirin», uning birligi bilan).
    existing_deleted = next((m for m in _yashirin
                             if str(item_data.unit or "").strip() == str(m.unit or "").strip()
                             and bool(is_peno) == bool(m.is_penoplast)), None) or (_yashirin[0] if _yashirin else None)

    qty = float(item_data.stock_quantity or 0)
    price = float(item_data.price_per_unit or 0)

    if existing_deleted is not None:
        e = existing_deleted
        # O'chirilgan material — faqat AYNAN shu birlik va turda tiklanadi (birligi / turi boshqa material retsept, harakat,
        # eski buyurtmalarda shu qator orqali ko'rinadi — uni boshqa narsaga aylantirib bo'lmaydi).
        if (str(item_data.unit or "").strip() != str(e.unit or "").strip()
                or bool(is_peno) != bool(e.is_penoplast)):
            raise MaterialNomiBand({
                "type": "material_nomi_yashirin",
                "message": (f"«{e.item_name}» nomi avval o'chirilgan (yashirilgan) materialda band (birligi: "
                            f"{e.unit or '—'}{', penoplast' if e.is_penoplast else ''}). Shu birlik va turda yarating — "
                            f"o'sha material tiklanadi — yoki boshqa nom tanlang"),
                "item_name": e.item_name,
                "unit": e.unit,
                "is_penoplast": bool(e.is_penoplast),
            })
        # Mayda birlik / koeffitsient YUBORILGAN bo'lsa — natijaviy holat tekshiriladi (eski koeffitsientsiz yozuv tiklashni to'smaydi).
        if 'base_unit' in _yuborilgan or 'conversion_factor' in _yuborilgan:
            _bu = item_data.base_unit if 'base_unit' in _yuborilgan else e.base_unit
            _cf = item_data.conversion_factor if 'conversion_factor' in _yuborilgan else e.conversion_factor
            _bx = _birlik_ogirish_xatosi(e.unit, _bu, _cf)
            if _bx:
                raise ValueError(_bx)
            # kech158 (zip 218, review218 №4 — O'LCHANGAN PG: retsept qatori «500 g» → «500 kg» bo'lardi): `update_item` qoidasi bilan bir
            _rb0, _rb1 = _retsept_birligi218(e.unit, e.base_unit, e.conversion_factor), _retsept_birligi218(e.unit, _bu, _cf)
            if _rb0 != _rb1 and material_ishlatilganmi(db, e, jadvallar=("bom_items",)):
                raise ValueError(f"«{e.item_name}» ishlab chiqarish retseptlarida ishlatilgan — retsept birligi «{_rb0}» dan «{_rb1}» ga "
                                 f"o'zgarib, retseptdagi miqdorlar «{_rb1}» deb o'qilib ketadi. Mayda birlik va koeffitsientni avvalgidek "
                                 f"qoldiring yoki boshqa nom bilan yangi material yarating")
        _eski_qty = float(e.stock_quantity or 0)
        _eski_narx = float(e.price_per_unit or 0)
        _eski_hajm = float(e.volume_per_unit or 1.0)
        e.is_deleted = False
        # Narx: kirim qoidasi (`_purchase_stock_no_commit`) — eski qoldiq musbat bo'lsa o'rtacha vaznli; eski qoldiq 0 /
        # manfiy bo'lsa yangi narx; yangi miqdorsiz (faqat narx) — eski musbat qoldiq narxi o'zgarmaydi.
        if item_data.price_per_unit is not None:
            _yn = float(item_data.price_per_unit)
            if qty > 0 and _eski_qty > 0:
                e.price_per_unit = round((_eski_qty * _eski_narx + qty * _yn) / (_eski_qty + qty), 2)
            elif qty > 0 or _eski_qty <= 0:
                e.price_per_unit = _yn
        # Blok hajmi (penoplast) — faqat YUBORILGAN bo'lsa (sxema standarti 1.0 — yuborilmasa eski hajm qoladi), xuddi
        # shu qoida (A-O06).
        if 'volume_per_unit' in _yuborilgan and item_data.volume_per_unit is not None:
            _yh = float(item_data.volume_per_unit)
            if qty > 0 and _eski_qty > 0:
                e.volume_per_unit = round((_eski_qty * _eski_hajm + qty * _yh) / (_eski_qty + qty), 4)
            elif qty > 0 or _eski_qty <= 0:
                e.volume_per_unit = _yh
        if 'min_stock' in _yuborilgan:
            e.min_stock = item_data.min_stock
        if getattr(item_data, 'category', None):
            e.category = item_data.category
        # 15-band (O'LCHANGAN): izoh berilmasa eski izoh saqlanadi (UI yaratish formasi izoh yubormaydi).
        if getattr(item_data, 'notes', None) is not None:
            e.notes = item_data.notes
        if 'base_unit' in _yuborilgan:
            e.base_unit = item_data.base_unit
        if 'conversion_factor' in _yuborilgan:
            e.conversion_factor = item_data.conversion_factor
        # Qoldiq: eski + yangi (hech qachon ustidan yozilmaydi); yangi miqdor — kirim harakati bilan.
        e.stock_quantity = _eski_qty + qty
        e.is_default_penoplast = bool(is_default and is_peno)
        if is_peno and is_default:
            # 2026-09-21 (O'LCHANGAN): tiklanayotgan pozitsiyaning o'zi UPDATE dan chiqariladi. Aks holda autoflush uning
            # `True` sini bazaga yozib, UPDATE uni `False` qilardi, xotiradagi `True` esa "o'zgarish yo'q" bo'lib qolardi —
            # korxonada birorta ham asosiy penoplast qolmasdi.
            _scope(db.query(Inventory).filter(
                Inventory.is_default_penoplast == True,
                Inventory.id != e.id)).update(
                {"is_default_penoplast": False}, synchronize_session=False
            )
            e.is_default_penoplast = True
        db.flush()
        if qty > 0:
            log_movement(db, e.id, e.item_name, "in", qty, unit=e.unit,
                         reason="Boshlang'ich qoldiq (o'chirilgan material qayta yaratilganda kiritilgan)",
                         performed_by=performed_by, company_id=e.company_id)
        # 15-band (O'LCHANGAN): boshlang'ich qoldiq xaridi — yangi qator yo'lidagi kabi (xarajat Moliyada ko'rinsin).
        if qty > 0 and price > 0:
            db.add(InventoryPurchase(
                inventory_id=e.id,
                item_name=e.item_name,
                quantity=qty,
                unit=e.unit,
                # 17g: narx va jami bazadagidek yaxlitlanadi (`_xarid_narx_jami`)
                price_per_unit=_xarid_narx_jami(qty, price)[0],
                total_amount=_xarid_narx_jami(qty, price)[1],
                notes="Boshlang'ich qoldiq (material yaratilganda kiritilgan)"
            ))
        # 15-band (O'LCHANGAN): korxonada asosiy penoplast qolmagan bo'lsa, shu penoplast asosiy bo'ladi.
        if is_peno and not e.is_default_penoplast:
            # kech37 (18-band): yashirin qatordagi eski asosiy belgi hisobga olinmaydi
            _bor = _scope(db.query(Inventory).filter(
                Inventory.is_default_penoplast == True,
                Inventory.id != e.id,
                Inventory.is_deleted.isnot(True)
            )).first()
            if not _bor:
                e.is_default_penoplast = True
        db.commit()
        db.refresh(e)
        return e

    # Yangi material
    _bx = _birlik_ogirish_xatosi(item_data.unit, getattr(item_data, 'base_unit', None),
                                 getattr(item_data, 'conversion_factor', None))
    if _bx:
        raise ValueError(_bx)

    # Agar asosiy deb belgilangan bo'lsa — eskisini bekor qilamiz
    if is_peno and is_default:
        _scope(db.query(Inventory).filter(Inventory.is_default_penoplast == True)).update(
            {"is_default_penoplast": False}, synchronize_session=False
        )

    db_item = Inventory(
        company_id=company_id,
        item_name=item_data.item_name,
        stock_quantity=item_data.stock_quantity,
        unit=item_data.unit,
        min_stock=item_data.min_stock,
        price_per_unit=item_data.price_per_unit,
        volume_per_unit=item_data.volume_per_unit,
        is_penoplast=is_peno,
        is_default_penoplast=(is_default and is_peno),
        category=(item_data.category if getattr(item_data, 'category', None) else guess_category(item_data.item_name, is_peno)),
        notes=item_data.notes,
        base_unit=getattr(item_data, 'base_unit', None),
        conversion_factor=getattr(item_data, 'conversion_factor', None)
    )
    db.add(db_item)
    db.flush()

    # kech142 (zip 170, A-O05 d): boshlang'ich qoldiq — ombor harakati bilan (narxsiz ham; xarid — faqat narx bo'lsa).
    if qty > 0:
        log_movement(db, db_item.id, db_item.item_name, "in", qty, unit=db_item.unit,
                     reason="Boshlang'ich qoldiq (material yaratilganda kiritilgan)",
                     performed_by=performed_by, company_id=company_id)

    # MUHIM: agar boshlang'ich miqdor (va narx) kiritilgan bo'lsa —
    # bu ham HAQIQIY xarajat, shuning uchun uni ham "xarid" tarixiga
    # yozamiz. Aks holda bu pul Moliya hisobotlarida umuman ko'rinmay
    # qolar edi (faqat ombor miqdori yozilib, xarajat qayd etilmasdi).
    if qty > 0 and price > 0:
        purchase = InventoryPurchase(
            inventory_id=db_item.id,
            item_name=db_item.item_name,
            quantity=qty,
            unit=db_item.unit,
            # 17g: narx va jami bazadagidek yaxlitlanadi (`_xarid_narx_jami`)
            price_per_unit=_xarid_narx_jami(qty, price)[0],
            total_amount=_xarid_narx_jami(qty, price)[1],
            notes="Boshlang'ich qoldiq (material yaratilganda kiritilgan)"
        )
        db.add(purchase)

    # Agar birinchi penoplast bo'lsa — avtomatik asosiy qilamiz
    # kech37 (18-band): yashirilgan (o'chirilgan) qatordagi eski asosiy belgi
    # hisobga olinmaydi — aks holda korxonada ko'rinadigan asosiy penoplast
    # bo'lmasa ham yangi penoplast asosiy bo'lmasdi (PG da O'LCHANGAN).
    if is_peno:
        has_default = _scope(db.query(Inventory).filter(
            Inventory.is_default_penoplast == True,
            Inventory.is_deleted.isnot(True)
        )).first()
        if not has_default:
            db_item.is_default_penoplast = True

    db.commit()
    db.refresh(db_item)
    return db_item


def get_inventory(db: Session, company_id: int = None) -> List[Inventory]:
    """Barcha xomashyo ro'yxatini qaytaradi (o'chirilganlar bundan mustasno)."""
    q = db.query(Inventory).filter(Inventory.is_deleted.isnot(True))
    if company_id is not None:
        q = q.filter(Inventory.company_id == company_id)
    return q.order_by(Inventory.item_name).all()


def get_item(db: Session, item_id: int, company_id: int = None) -> Optional[Inventory]:
    """ID bo'yicha bitta xomashyoni qaytaradi.

    2026-09-18 — M3: company_id berilsa, material FAQAT shu korxonadan
    qidiriladi. Berilmasa — eski xatti-harakat (ichki, allaqachon
    tekshirilgan oqimlar uchun). Tashqi chaqiruvlar company_id uzatadi."""
    q = db.query(Inventory).filter(Inventory.id == item_id)
    if company_id is not None:
        q = q.filter(Inventory.company_id == company_id)
    return q.first()


def get_item_locked(db: Session, item_id: int, company_id: int = None) -> Optional[Inventory]:
    """ID bo'yicha xomashyoni QULFLAB qaytaradi (SELECT ... FOR UPDATE).

    Bir nechta foydalanuvchi AYNI shu xomashyoni bir vaqtda o'zgartirmoqchi
    bo'lsa — ikkinchisi birinchisi tugaguncha (millisekundlar) kutadi,
    shunda hech kimning o'zgartirishi "yo'qolib" ketmaydi.
    Faqat MIQDORNI O'ZGARTIRISH kerak bo'lgan joylarda ishlatiladi —
    oddiy ko'rish/ro'yxat uchun emas (aks holda keraksiz sekinlik yaratadi).
    PostgreSQL'da haqiqiy qulflaydi; SQLite'da (test muhiti) e'tiborsiz qoldiriladi.

    kech142 (zip 170, A-O04): qiymatlar bazadan QAYTA yuklanadi — `inventory_qulf` izohi."""
    return inventory_qulf(db, item_id, company_id)


def inventory_qulf_sorov(db: Session, q, ochirish: bool = False):
    """kech142 (zip 170, A-O04 — O'LCHANGAN HAQIQIY PG `work/audit/tasdiq/ombor/p_o04b.py` S6): material (Inventory)
    qatorini `SELECT … FOR UPDATE` bilan qulflaydi VA qiymatlarini bazadan QAYTA yuklaydi (`populate_existing`).

    Sabab: sessiya shu qatorni OLDIN qulfsiz o'qigan bo'lsa (masalan tekshiruv yoki boshqa obyekt orqali — `fp.penoplast`,
    `ing.inventory`), `FOR UPDATE` boshqa tranzaksiyaning commit ini KUTADI, lekin SQLAlchemy sessiyadagi ESKI obyektni
    eski qiymatlari bilan qaytaradi; chaqiruvchi esa mutlaq qiymat yozadi (`p.stock_quantity = eski − blok`) — parallel
    kirim YO'QOLARDI (penoplast 119.95 + 10 kirim − 0.05 → 119.9, to'g'risi 129.85; qoldiq ≠ Σ harakat).
    - Avval `flush` — sessiyadagi yozilmagan o'zgarish `populate_existing` da yo'qolmasin (`SessionLocal` autoflush=False;
      `_fp_qulf` naqshi).
    - `q` — `db.query(Inventory)…` (chaqiruvchining filtrlari bilan: id, korxona); natija — bitta qator yoki None.
    - kech155 (zip 199 — O'LCHANGAN HAQIQIY PG R7 / R10 / R11, 3 / 3 urinishda 40P01): qulf `FOR NO KEY UPDATE` (`key_share=True`;
      `_fp_qulf` kech145 naqshi). Detal / harakat yozilganda PG xomashyo qatoriga tashqi kalit KEY SHARE qulfini qo'yadi; oddiy
      `FOR UPDATE` u bilan to'qnashardi — buyurtma tahriri (guruh → penoplast) ∥ buyurtma yaratish (penoplast KEY SHARE → guruh)
      va taqdirli brak bekori (partiya → penoplast) ∥ buyurtma bir-birini kutib qolardi (biri 500). NO KEY UPDATE o'zaro (va UPDATE
      bilan) baribir bir-birini kutadi — qoldiqni o'zgartirish navbati o'zgarmaydi. `ochirish=True` — qatorni O'CHIRADIGAN joy
      (`delete_item`): oddiy `FOR UPDATE` (yangi tashqi kalit bog'lanishini ham to'xtatadi)."""
    db.flush()
    if ochirish:
        return q.populate_existing().with_for_update().first()
    return q.populate_existing().with_for_update(key_share=True).first()


def inventory_qulf(db: Session, item_id, company_id: int = None, ochirish: bool = False) -> Optional[Inventory]:
    """kech142 (zip 170, A-O04): id (va korxona) bo'yicha material qatori — QULFLANGAN va bazadan QAYTA yuklangan
    (`inventory_qulf_sorov`; kech155 — `FOR NO KEY UPDATE`, `ochirish=True` — `FOR UPDATE`). id bo'sh bo'lsa — None."""
    if not item_id:
        return None
    q = db.query(Inventory).filter(Inventory.id == item_id)
    if company_id is not None:
        q = q.filter(Inventory.company_id == company_id)
    return inventory_qulf_sorov(db, q, ochirish=ochirish)


# ============================================================
# kech117 (A2) — YO'NALISHLAR (egasi QARORLARI kech114 00:08 — QAYTA SO'RALMAYDI)
# ============================================================
# Korxona o'z ish yo'nalishlarini yuritadi («Penoplast» — asosiy, kodda doimiy qolgan turkumlar shunga; boshqalarini o'zi
# qo'shadi, nomini o'zgartiradi, ishlatilganini faqat yashiradi). Hodim, xarajat, transport, kirim va MRP mahsulot turi
# `yonalish_id` bilan bog'lanadi (NULL — «Umumiy»; MRP turida — «Belgilanmagan»). Hisob — `services.
# calculate_split_profit_report` (har yo'nalish sof foydasi, yig'indisi = Moliyadagi sof foyda).
_YONALISH_NOM_MAX = 60
_YON_YOQ = object()      # "kalit yuborilmagan" belgisi (None — «Umumiy» tanlangan degani)


def standart_yonalish(db: Session, company_id: int, yarat: bool = True):
    """Korxonaning ASOSIY yo'nalishi (`kod = 'penoplast'`). Yo'q bo'lsa va `yarat` — yaratiladi (faqat `flush`;
    `commit` — chaqiruvchida). PostgreSQL da parallel yaratish `uq_yonalishlar_company_kod` bilan to'siladi:
    savepoint ichida urinib, band bo'lsa mavjudini qaytaradi."""
    from models import Yonalish, YONALISH_ASOSIY_KOD, YONALISH_ASOSIY_NOM
    from sqlalchemy.exc import IntegrityError as _IE117
    if company_id is None:
        return None
    y = db.query(Yonalish).filter(Yonalish.company_id == company_id,
                                  Yonalish.kod == YONALISH_ASOSIY_KOD).first()
    if y is not None or not yarat:
        return y
    y = Yonalish(company_id=company_id, nom=YONALISH_ASOSIY_NOM, kod=YONALISH_ASOSIY_KOD,
                 yashirin=False, tartib=0)
    if db.bind.dialect.name == "postgresql":
        try:
            with db.begin_nested():
                db.add(y)
                db.flush()
        except _IE117:
            return db.query(Yonalish).filter(Yonalish.company_id == company_id,
                                             Yonalish.kod == YONALISH_ASOSIY_KOD).first()
    else:
        db.add(y)
        db.flush()
    return y


def yonalishlar_royxati(db: Session, company_id: int, yashirinlar: bool = False) -> list:
    """Korxona yo'nalishlari: asosiy birinchi, keyin `tartib`, `id`. `yashirinlar=False` — faqat ko'rinadiganlar
    (yangi yozuv tanlovi uchun). Asosiy yo'nalish yo'q bo'lsa — yaratiladi (flush)."""
    from models import Yonalish, YONALISH_ASOSIY_KOD
    if company_id is None:
        return []
    standart_yonalish(db, company_id)
    q = db.query(Yonalish).filter(Yonalish.company_id == company_id)
    if not yashirinlar:
        q = q.filter((Yonalish.yashirin.is_(None)) | (Yonalish.yashirin.is_(False)))
    royxat = q.all()
    return sorted(royxat, key=lambda y: (0 if y.kod == YONALISH_ASOSIY_KOD else 1, y.tartib or 0, y.id))


def yonalish_of_company(db: Session, yonalish_id, company_id: int):
    """Yo'nalish FAQAT shu korxonadan (begona / yo'q — None)."""
    from models import Yonalish
    if yonalish_id is None or company_id is None:
        return None
    return db.query(Yonalish).filter(Yonalish.id == yonalish_id, Yonalish.company_id == company_id).first()


def yonalish_dict(y) -> dict:
    return {"id": y.id, "nom": y.nom, "asosiy": bool(y.asosiy), "yashirin": bool(y.yashirin)}


def _yonalish_nomi_toza(nom) -> str:
    if not isinstance(nom, str):
        raise ValueError("Yo'nalish nomi matn bo'lishi kerak")
    toza = " ".join(nom.split())
    if not toza:
        raise ValueError("Yo'nalish nomini kiriting")
    if len(toza) > _YONALISH_NOM_MAX:
        raise ValueError(f"Yo'nalish nomi juda uzun ({_YONALISH_NOM_MAX} belgidan ko'p)")
    return toza


def _yonalish_nomi_bandmi(db: Session, company_id: int, nom: str, istisno_id=None) -> bool:
    """Ko'rinadigan yo'nalishlar orasida bir xil nom (katta / kichik harf farqsiz) bormi."""
    for y in yonalishlar_royxati(db, company_id):
        if y.id != istisno_id and y.nom.strip().lower() == nom.lower():
            return True
    return False


def yonalish_yarat(db: Session, company_id: int, nom, created_by: str = None):
    """Yangi yo'nalish. Nom 1–60 belgi, ko'rinadiganlar orasida takrorlanmaydi. Xato — `ValueError`."""
    from models import Yonalish
    toza = _yonalish_nomi_toza(nom)
    if _yonalish_nomi_bandmi(db, company_id, toza):
        raise ValueError(f"«{toza}» nomli yo'nalish allaqachon bor")
    oxirgi = max([y.tartib or 0 for y in yonalishlar_royxati(db, company_id, yashirinlar=True)] or [0])
    y = Yonalish(company_id=company_id, nom=toza, kod=None, yashirin=False, tartib=oxirgi + 1,
                 created_by=created_by)
    db.add(y)
    db.flush()
    log_activity(db, "created", "yonalish", y.id, f"Yo'nalish «{y.nom}»", created_by,
                 company_id=company_id, commit=False)
    db.commit()
    db.refresh(y)
    return y


def yonalish_yangila(db: Session, yonalish_id: int, company_id: int, data: dict, kim: str = None):
    """Nomini o'zgartirish (`nom`) va / yoki yashirish / ko'rsatish (`yashirin`). Asosiy yo'nalish yashirilmaydi.
    Noma'lum kalit / noto'g'ri tur — `ValueError`; topilmasa — None."""
    if not isinstance(data, dict):
        raise ValueError("Noto'g'ri so'rov")
    notogri = sorted(str(k)[:40] for k in data if k not in ("nom", "yashirin"))
    if notogri:
        raise ValueError("Bu maydonni o'zgartirib bo'lmaydi: " + ", ".join(notogri[:10]))
    y = yonalish_of_company(db, yonalish_id, company_id)
    if y is None:
        return None
    eski = f"{y.nom}{' (yashirin)' if y.yashirin else ''}"
    _eski183 = (y.nom, bool(y.yashirin))       # kech146 (zip 183, J5): qiymatlar (matn emas) solishtiriladi — mustaqil tekshiruv R2
    if "nom" in data:
        toza = _yonalish_nomi_toza(data["nom"])
        if _yonalish_nomi_bandmi(db, company_id, toza, istisno_id=y.id):
            raise ValueError(f"«{toza}» nomli yo'nalish allaqachon bor")
        y.nom = toza
    if "yashirin" in data:
        if not isinstance(data["yashirin"], bool):
            raise ValueError("'yashirin' true yoki false bo'lishi kerak")
        if data["yashirin"] and y.asosiy:
            raise ValueError("Asosiy yo'nalish yashirilmaydi — profil, panel, donali, blok va loy sotish "
                             "buyurtmalari shunga yoziladi (nomini o'zgartirish mumkin)")
        if not data["yashirin"] and y.yashirin and _yonalish_nomi_bandmi(db, company_id, y.nom, istisno_id=y.id):
            raise ValueError(f"«{y.nom}» nomli boshqa yo'nalish ko'rinib turibdi — avval nomini o'zgartiring")
        y.yashirin = data["yashirin"]
    yangi = f"{y.nom}{' (yashirin)' if y.yashirin else ''}"
    if (y.nom, bool(y.yashirin)) == _eski183:
        # kech146 (zip 183, audit J5 — O'LCHANGAN): o'zgarishsiz saqlash (yoki ikki marta bosish) jurnalga soxta «tahrirlandi» yozardi
        # (matn «Q (yashirin)» nomli ko'rinadigan yo'nalish bilan adashmasin — qiymatlar solishtiriladi)
        db.rollback()
        return y
    log_activity(db, "updated", "yonalish", y.id, f"Yo'nalish «{y.nom}»", kim, old_value=eski, new_value=yangi,
                 company_id=company_id, commit=False)
    db.commit()
    db.refresh(y)
    return y


_YONALISH_BOGLAMLARI = (
    ("employees", "Employee", "hodim"),
    ("expense_transactions", "ExpenseTransaction", "xarajat"),
    ("transport_expenses", "TransportExpense", "transport"),
    ("inventory_receipts", "InventoryReceipt", "kirim"),
    ("product_types", "ProductType", "MRP mahsulot turi"),
)


def yonalish_ishlatilishi(db: Session, yonalish_id: int, company_id: int) -> dict:
    """{nom: soni} — shu yo'nalishga bog'langan yozuvlar (o'chirilganlari ham — tarix buzilmasin)."""
    import models as _m117
    import production_models as _pm117
    from sqlalchemy import func as _f117
    natija = {}
    for _jadval, _model, _nom in _YONALISH_BOGLAMLARI:
        _cls = getattr(_m117, _model, None) or getattr(_pm117, _model)
        n = db.query(_f117.count(_cls.id)).filter(_cls.yonalish_id == yonalish_id,
                                                  _cls.company_id == company_id).scalar() or 0
        if n:
            natija[_nom] = int(n)
    return natija


def yonalish_ochir(db: Session, yonalish_id: int, company_id: int, kim: str = None):
    """Ishlatilmagan yo'nalishni o'chiradi. Asosiy — o'chirilmaydi; ishlatilgan — `ValueError` (faqat yashirish).
    Topilmasa — None; o'chirilsa — True."""
    y = yonalish_of_company(db, yonalish_id, company_id)
    if y is None:
        return None
    if y.asosiy:
        raise ValueError("Asosiy yo'nalish o'chirilmaydi")
    ish = yonalish_ishlatilishi(db, yonalish_id, company_id)
    if ish:
        raise ValueError("Bu yo'nalish ishlatilgan (" + ", ".join(f"{k}: {v}" for k, v in ish.items())
                         + ") — o'chirib bo'lmaydi, faqat yashirish mumkin")
    nom = y.nom
    db.delete(y)
    log_activity(db, "deleted", "yonalish", yonalish_id, f"Yo'nalish «{nom}»", kim, company_id=company_id,
                 commit=False)
    db.commit()
    return True


def yonalish_tanlovi(db: Session, company_id: int, yonalish_id=_YON_YOQ, production_type=_YON_YOQ,
                     joriy_id=None):
    """Yozuvga yoziladigan (yonalish_id, production_type) juftligi — YAGONA qoida (hodim, xarajat, transport, kirim).

    * `yonalish_id` yuborilgan (None ham) — YANGI tanlov: None — «Umumiy»; son — shu korxonaning yo'nalishi bo'lishi
      SHART (begona / yo'q — `ValueError` "topilmadi", oracle yo'q), yashirin bo'lsa faqat o'zgarmagan (joriy)
      qiymat qabul qilinadi. Eski `production_type` belgisi — asosiy yo'nalishda 'penoplast', aks holda None (shunda
      ishga tushish migratsiyasi uni qayta asosiyga o'tkazmaydi).
    * Faqat eski `production_type` (API / eski sahifa): 'penoplast' — asosiy yo'nalish; boshqa qiymat ('umumiy',
      'gips', bo'sh) — «Umumiy», matn o'zgarmay saqlanadi (Gips moliyadan olib tashlangan — egasi qarori kech114).
    * Ikkalasi ham yo'q — (`_YON_YOQ`, `_YON_YOQ`): o'zgarmaydi (tahrirda)."""
    from models import YONALISH_ASOSIY_KOD
    if yonalish_id is not _YON_YOQ:
        if yonalish_id is None:
            return None, None
        y = yonalish_of_company(db, yonalish_id, company_id)
        if y is None:
            raise ValueError("Yo'nalish topilmadi")
        if y.yashirin and y.id != joriy_id:
            raise ValueError(f"«{y.nom}» yo'nalishi yashirilgan — avval uni Sozlamalarda ko'rsating")
        return y.id, (YONALISH_ASOSIY_KOD if y.kod == YONALISH_ASOSIY_KOD else None)
    if production_type is not _YON_YOQ:
        if production_type == YONALISH_ASOSIY_KOD:
            s = standart_yonalish(db, company_id)
            return (s.id if s is not None else None), YONALISH_ASOSIY_KOD
        return None, production_type
    return _YON_YOQ, _YON_YOQ


def yonalish_nomlari(db: Session, company_id: int) -> dict:
    """{id: nom} — korxonaning HAMMA yo'nalishi (yashirinlari ham) — ro'yxatlarda nom ko'rsatish uchun."""
    return {y.id: y.nom for y in yonalishlar_royxati(db, company_id, yashirinlar=True)}


def create_expense_transaction(db: Session, data, performed_by: Optional[str] = None, source: str = "manual",
                               company_id: int = None):
    """Yangi xarajat tranzaksiyasini yaratadi. Bu funksiya faqat YANGI ExpenseTransaction
    jadvaliga yozadi — mavjud MonthlyExpense yoki hisob-kitob logikasiga umuman tegmaydi."""
    from models import ExpenseTransaction
    # 17e (2026-09-22): ILDIZ — tana QAT'IY (summa musbat va chekli,
    # kategoriya 1–30 belgi, yo'nalish ro'yxatdan, sana 2000–2100).
    # Marshrut ham tekshiradi; bu qatlam boshqa chaqiruvchilar uchun.
    data = _clean_val("ExpenseTransaction", _val_dump(data, "ExpenseTransaction"))
    # kech117 (A2): yo'nalish — YAGONA qoida (`yonalish_tanlovi`; begona / yo'q / yashirin — ValueError, hech narsa
    # yozilmaydi). Hech biri yuborilmasa — «Umumiy».
    _yid, _pt = yonalish_tanlovi(db, company_id, data.get("yonalish_id", _YON_YOQ),
                                 data.get("production_type", _YON_YOQ))
    if _yid is _YON_YOQ:
        _yid, _pt = None, None
    # kech155 (zip 210): qaysi pul hisobidan (berilmasa — «Naqd pul»; noto'g'ri — ValueError, hech narsa yozilmaydi)
    _hid210 = pul_hisobi_id(db, company_id, hisob=data.get("hisob"))
    # M6 — TENANT: company_id ANIQ beriladi (ota-FK yo'q, DEFAULT 1 ga tushmasin).
    tx = ExpenseTransaction(
        company_id=company_id,
        date=data.get("date") or datetime.utcnow(),
        category=data["category"],
        amount=data.get("amount", 0),
        notes=data.get("notes"),
        created_by=performed_by,
        source=source,
        production_type=_pt,
        yonalish_id=_yid,
        hisob_id=_hid210,
        # kech155 (zip 210, review210 №1): sana hisobot oyi, pul HOZIR — hisob qoldig'i shu payt bilan (`services._pul_keyin`)
        pul_vaqti=(datetime.utcnow() if data.get("pul_hozir") else None),
    )
    db.add(tx)
    db.commit()
    db.refresh(tx)
    return tx


def update_expense_transaction(db: Session, tx_id: int, data,
                               company_id: int = None) -> Optional["ExpenseTransaction"]:
    """2026-09-16: foydalanuvchi so'rovi bo'yicha qo'shildi — xato kiritilgan
    summani (masalan "125 000" o'rniga "125") o'chirib-qayta yozish o'rniga,
    to'g'ridan-to'g'ri TAHRIRLASH imkonini beradi. create_expense_transaction
    kabi — faqat shu BITTA ExpenseTransaction yozuvini yangilaydi, boshqa
    hech qanday jadval yoki hisob-kitobga (Kassa balansi va h.k. — bular
    har safar JORIY yozuvlar asosida qayta hisoblanadi) alohida ta'sir
    qilmaydi."""
    from models import ExpenseTransaction
    # 17e (2026-09-22): ILDIZ — yaratish bilan BIR XIL qat'iy qoida
    # (bazaga tegishdan OLDIN; xato → `ValueError`, hech narsa yozilmaydi).
    data = _clean_val("ExpenseTransaction", _val_dump(data, "ExpenseTransaction"))
    _q = db.query(ExpenseTransaction).filter(ExpenseTransaction.id == tx_id)
    if company_id is not None:      # M6: faqat shu korxonadan
        _q = _q.filter(ExpenseTransaction.company_id == company_id)
    tx = _q.first()
    if not tx:
        return None
    # kech155 (zip 210): hisob yuborilsa — o'zgaradi (avval tekshiriladi: noto'g'ri — ValueError, hech narsa o'zgarmaydi)
    _hid210 = pul_hisobi_id(db, tx.company_id, hisob=data["hisob"]) if data.get("hisob") else None
    if _hid210 is not None:
        tx.hisob_id = _hid210
    if "date" in data and data["date"]:
        tx.date = data["date"]
    if "category" in data and data["category"]:
        tx.category = data["category"]
    if "amount" in data and data["amount"] is not None:
        tx.amount = data["amount"]
    if "notes" in data:
        tx.notes = data["notes"]
    # kech117 (A2): yo'nalish — yaratish bilan BIR qoida; kalit yuborilmasa o'zgarmaydi. Yashirin yo'nalishli eski
    # yozuvni tahrirlash (yo'nalishi o'zgarmasa) — ruxsat.
    _yid, _pt = yonalish_tanlovi(db, company_id if company_id is not None else tx.company_id,
                                 data.get("yonalish_id", _YON_YOQ), data.get("production_type", _YON_YOQ),
                                 joriy_id=tx.yonalish_id)
    if _yid is not _YON_YOQ:
        tx.yonalish_id = _yid
        tx.production_type = _pt
    db.commit()
    db.refresh(tx)
    return tx


def get_expense_transactions(db: Session, year: Optional[int] = None, month: Optional[int] = None,
                              day: Optional[int] = None, category: Optional[str] = None, limit: int = 200,
                              company_id: int = None):
    """Xarajat tranzaksiyalari ro'yxati — faqat o'qish (M6 — tenant-safe)."""
    from models import ExpenseTransaction
    from datetime import date as _date_kx
    q = db.query(ExpenseTransaction)
    if company_id is not None:
        q = q.filter(ExpenseTransaction.company_id == company_id)
    # kech105 (9 + 50-band, QAROR "Toshkent vaqti bo'yicha"): yil / oy / kun — TOSHKENT kalendari (ilgari UTC
    # `extract` — Toshkent vaqti bilan 00:00–05:00 dagi xarajat oldingi kun / oyda chiqardi).
    if (month and not year) or (day and not (year and month)):
        raise ValueError("Oy filtri faqat yil bilan, kun filtri — yil va oy bilan birga beriladi")
    if year and month and day:
        q = q.filter(_tashkent_kunida(ExpenseTransaction.date, _date_kx(int(year), int(month), int(day))))
    elif year and month:
        q = q.filter(_tashkent_oyida(ExpenseTransaction.date, year, month))
    elif year:
        q = q.filter(_tashkent_yilida(ExpenseTransaction.date, year))
    if category:
        q = q.filter(ExpenseTransaction.category == category)
    return q.order_by(ExpenseTransaction.date.desc()).limit(limit).all()


def delete_expense_transaction(db: Session, tx_id: int, company_id: int = None) -> bool:
    from models import ExpenseTransaction
    _q = db.query(ExpenseTransaction).filter(ExpenseTransaction.id == tx_id)
    if company_id is not None:      # M6: faqat shu korxonadan
        _q = _q.filter(ExpenseTransaction.company_id == company_id)
    tx = _q.first()
    if not tx:
        return False
    db.delete(tx)
    db.commit()
    return True


def log_movement(db: Session, inventory_id: Optional[int], item_name: str, movement_type: str,
                  quantity: float, unit: Optional[str] = None, reason: Optional[str] = None,
                  order_id: Optional[int] = None, supplier_id: Optional[int] = None,
                  performed_by: Optional[str] = None, notes: Optional[str] = None,
                  company_id: Optional[int] = None, is_brak: Optional[bool] = None,
                  unit_cost: Optional[float] = None):
    """Ombor harakati jurnaliga bitta yozuv qo'shadi.

    kech107 (36-band): `unit_cost` — CHIQIM narxi berilsa (masalan tayyor loy zaxirasi: olingan paytdagi retsept
    tannarxi — pozitsiyaning o'z narxi yo'q), shu narx muzlatiladi; berilmasa — avvalgidek materialning joriy narxi.

    kech52 (13-band, 3-qadam): `is_brak` — brak harakati belgisi (hisobot shu
    belgiga qaraydi, sabab matniga emas). Berilmasa: CHIQIM brak oynasi ichida
    bo'lsa True — `create_return_item` brak yozuvi raqamini
    (`db.info["_brak_qaytarish_id"]`) yoki ishlab chiqarish braki
    `db.info["_brak_harakat"]` belgisini sessiyaga qo'yadi (chuqur `services`
    chaqiruvlari — tayyor loy, loy ingredientlari — ham shu yo'l bilan
    belgilanadi); aks holda False. Hech qachon NULL yozilmaydi.

    MUHIM: bu funksiya faqat LOG yozadi — hech qanday hisob-kitobga yoki
    stock_quantity qiymatiga ta'sir qilmaydi. Xato yuz bersa ham asosiy
    amalni to'xtatmaslik uchun try/except bilan o'ralgan."""
    from models import InventoryMovement
    try:
        if quantity is None or quantity == 0:
            return
        # M8/F1: uchala ota-FK (`inventory_id`, `order_id`, `supplier_id`)
        # ham NULL bo'lishi mumkin (o'chirilgan material bo'yicha harakat) —
        # bunday holatda qo'riqchi korxonani aniqlay olmaydi.
        _cid = company_id
        if _cid is None and inventory_id:
            _inv_row = db.query(Inventory.company_id).filter(Inventory.id == inventory_id).first()
            _cid = _inv_row[0] if _inv_row else None
        # kech45 (13-band, 6-qadam): `create_return_item` brak xomashyosini
        # yechayotganda sessiyaga brak yozuvi raqamini qo'yadi — shu oraliqda
        # yozilgan HAR harakat (penoplast, tayyor loy, loy ingredientlari —
        # `services` ichidagi chuqur chaqiruvlar ham) unga bog'lanadi.
        _brak_rid = db.info.get("_brak_qaytarish_id") if movement_type == "out" else None
        # kech125 (zip 146): tayyor mahsulot braki yozuvi (ishlab chiqarish braki xomashyosi, taqdir harakatlari) va taqdir
        # qatori — `create_return_item` dagi `_brak_qaytarish_id` kabi sessiya belgisidan (faqat chiqim).
        _brak_fpl = db.info.get("_brak_yoqotish_id") if movement_type == "out" else None
        _brak_tq = db.info.get("_brak_taqdir_id") if movement_type == "out" else None
        if is_brak is None:
            _brak = movement_type == "out" and (_brak_rid is not None
                                                or _brak_fpl is not None
                                                or bool(db.info.get("_brak_harakat")))
        else:
            _brak = bool(is_brak)
        # kech46 (13-band, 2-qadam): chiqim paytidagi 1 birlik narxi muzlatiladi.
        # `db.get` — sessiyadagi (hali yozilmagan) o'zgarishni ham ko'radi.
        # Narx belgilanmagan material — 0 (hisobot ham 0 deb hisoblardi).
        # Material topilmasa (o'chirilgan) — NULL. Narxni o'qish yiqilsa ham
        # harakat YOZILADI (narxsiz — hisobot joriy narxni oladi): tashqi
        # `except` butun harakatni tashlab yuborardi (kech46 M04 da O'LCHANDI).
        _narx = None
        if movement_type == "out" and inventory_id and unit_cost is not None:
            # kech107 (36-band): chaqiruvchi bergan narx (tayyor loy zaxirasi — retsept tannarxi).
            try:
                _narx = float(unit_cost)
            except (TypeError, ValueError):
                _narx = None
        elif movement_type == "out" and inventory_id:
            try:
                _inv_narx = db.get(Inventory, inventory_id)
                if _inv_narx is not None:
                    _narx = float(_inv_narx.price_per_unit or 0)
            except Exception:
                _narx = None
        db.add(InventoryMovement(
            company_id=_cid,
            inventory_id=inventory_id, item_name=item_name, movement_type=movement_type,
            quantity=abs(float(quantity)), unit=unit, reason=reason,
            order_id=order_id, supplier_id=supplier_id,
            performed_by=performed_by, notes=notes,
            return_item_id=_brak_rid,
            fp_loss_id=_brak_fpl,
            brak_taqdir_id=_brak_tq,
            unit_cost=_narx,
            is_brak=_brak
        ))
    except Exception as e:
        try:
            log_error(db, str(e), endpoint="log_movement")
        except Exception:
            pass


# Qo'lda qoldiq tuzatish (`POST /api/inventory/{id}/stock`) tanasi —
# 19-band (2026-09-21). Harakat jurnali `reason` ustuni String(200):
# uzunroq izoh PostgreSQL da commit paytida 500 berardi.
_STOCK_REASON_MAX = 200


def _jurnal_sabab(matn) -> str:
    """20-band (2026-09-21): ombor jurnali `reason` ustuni String(200).
    Nom qo'shiladigan sabablar (mahsulot nomi 150 belgigacha) ustundan oshsa
    PostgreSQL COMMIT paytida yiqiladi (`log_movement` ichidagi try/except
    uni USHLAMAYDI — `db.add` o'tadi, xato keyin chiqadi). Shuning uchun
    sabab 200 belgiga xavfsiz qisqartiriladi."""
    matn = "" if matn is None else str(matn)
    return matn if len(matn) <= _STOCK_REASON_MAX else matn[:_STOCK_REASON_MAX - 1] + "…"


def _stock_son(value):
    """`quantity_change` — ishorali (musbat = kirim, manfiy = chiqim), chekli,
    0 emas, `true/false` emas, sig'imdan katta emas. Aks holda ValueError."""
    import math
    if value is None:
        raise ValueError("'quantity_change' bo'sh bo'lishi mumkin emas")
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError("'quantity_change' son bo'lishi kerak")
    v = float(value)
    if math.isnan(v) or math.isinf(v):
        raise ValueError("'quantity_change' son bo'lishi kerak")
    if v == 0:
        raise ValueError("'quantity_change' 0 bo'lishi mumkin emas")
    if abs(v) > _UPD_SON_CHEGARA:
        raise ValueError("'quantity_change' juda katta")
    return v


def _clean_stock_change(data) -> dict:
    """Marshrut tanasi (xom JSON) → {"quantity_change", "reason"}.
    Ruxsat ro'yxati + qat'iy turlar; buzilsa ValueError (→ 400)."""
    if not isinstance(data, dict):
        raise ValueError("Noto'g'ri so'rov")
    notogri = sorted(str(k)[:40] for k in data if k not in ("quantity_change", "reason"))
    if notogri:
        raise ValueError("Noma'lum maydon: " + ", ".join(notogri[:10]))
    qc = _stock_son(data.get("quantity_change"))
    reason = data.get("reason")
    if reason is not None:
        if not isinstance(reason, str):
            raise ValueError("'reason' matn bo'lishi kerak")
        if len(reason) > _STOCK_REASON_MAX:
            raise ValueError(f"'reason' juda uzun ({_STOCK_REASON_MAX} belgidan ko'p)")
    return {"quantity_change": qc, "reason": reason}


# kech52 (13-band, 3-qadam, 38-band qarori "C"): Omborxonadagi qo'lda "Chiqim" izohi shu
# so'z bilan boshlansa — o'sha chiqim brak xarajati hisoblanadi (`update_stock`).
QOLDA_BRAK_BOSHI = "Brak"


def update_stock(db: Session, item_id: int, quantity_change: float, performed_by: Optional[str] = None,
                 notes: Optional[str] = None, company_id: int = None) -> Optional[Inventory]:
    """Mahsulot qoldig'ini yangilaydi (musbat = qo'shish, manfiy = ayirish).
    Narxsiz oddiy tuzatish uchun (masalan inventarizatsiya). Xarid uchun
    purchase_stock() dan foydalaning — u narxni ham hisobga oladi.

    19-band (2026-09-21, O'LCHANGAN): ilgari chiqim qoldiqdan ko'p bo'lsa
    qoldiq JIMGINA 0 ga qirqilardi, jurnalga esa so'ralgan to'liq miqdor
    yozilardi (qoldiq 100, chiqim 1000 → 0, harakat "out 1000"). Loy
    qoldig'i endi manfiy bo'lishi mumkin (foydalanuvchi qarori) — bu
    qirqish MANFIY qoldiqdagi qarzni o'chirib yuborardi (-30 da 5 chiqim →
    0, ya'ni +30). Endi: chiqim mavjud qoldiqdan (manfiy bo'lsa — 0 dan)
    ko'p bo'lsa ValueError (→ 400), hech narsa yozilmaydi; kirim (musbat)
    arifmetik — manfiy qoldiqni qoplaydi. Qiymat HECH NARSA yozilmasdan
    OLDIN qat'iy tekshiriladi (NaN/cheksiz/bool/0 — ValueError)."""
    qc = _stock_son(quantity_change)
    if notes is not None and len(str(notes)) > _STOCK_REASON_MAX:
        raise ValueError(f"'reason' juda uzun ({_STOCK_REASON_MAX} belgidan ko'p)")
    db_item = get_item_locked(db, item_id, company_id)
    if not db_item:
        return None
    current = float(db_item.stock_quantity or 0)
    if qc < 0:
        mavjud = max(current, 0.0)
        if -qc > mavjud + 1e-9:
            if current < 0:
                raise ValueError(
                    f"{db_item.item_name}: qoldiq manfiy ({_miqdor_matn(current)} {db_item.unit}) — "
                    f"chiqim qilib bo'lmaydi, avval kirim qiling")
            raise ValueError(
                f"{db_item.item_name}: omborda {_miqdor_matn(current)} {db_item.unit} bor — "
                f"{_miqdor_matn(-qc)} {db_item.unit} chiqim qilib bo'lmaydi")
    new_qty = current + qc
    if -1e-9 < new_qty < 0:
        new_qty = 0.0
    db_item.stock_quantity = new_qty
    log_movement(
        db, db_item.id, db_item.item_name,
        movement_type="in" if qc > 0 else "out",
        quantity=qc, unit=db_item.unit,
        reason=notes or "Qo'lda tuzatish (inventarizatsiya)", performed_by=performed_by,
        # kech52 (13-band, 3-qadam) — FOYDALANUVCHI QARORI (38-band, tugma bilan): "C — izoh
        # 'Brak' bilan boshlansa, brak hisoblansin (hozirgidek)". Qo'lda CHIQIM izohi
        # QOLDA_BRAK_BOSHI bilan boshlansa — brak xarajati (Moliya, sof foyda). Katta-kichik
        # harfga SEZGIR — Railway (PostgreSQL) dagi avvalgi `LIKE 'Brak%'` xulqi bilan AYNAN
        # (kichik harfli "brak" avval SQLite da brak, PG da brak EMAS edi — endi ikkala bazada
        # bir xil: EMAS). Belgi YOZISH paytida bir marta aniqlanadi, keyin matnga qaralmaydi.
        is_brak=(qc < 0 and str(notes or "").startswith(QOLDA_BRAK_BOSHI))
    )
    db.commit()
    db.refresh(db_item)
    return db_item


def guess_category(item_name: str, is_penoplast: bool = False) -> str:
    """Material nomidan kategoriyani taxmin qiladi.

    3 asosiy guruh:
    1) Penoplast — penoplast xomashyosi
    2) Kimyoviy qo'shimchalar — suyuq/kimyoviy moddalar (akril, pva, zagustitel, penogasitel)
    3) Qattiq qotishmalar — qum, mel, kroshka va shunga o'xshash quruq materiallar
    """
    name = (item_name or '').lower()
    if is_penoplast or 'penoplast' in name or 'penopleks' in name:
        return "Penoplast"
    if any(k in name for k in ['akril', 'pva', 'zagustitel', 'penogasitel', 'texanol', 'biosid', 'hpmc']):
        return "Kimyoviy qo'shimchalar"
    if any(k in name for k in ['qum', 'kroshka', "shag'al", 'mel', 'kvars', 'mikroklasit', 'mikrokalsit']):
        return "Qattiq qotishmalar"
    return "Boshqa"


def purchase_stock(db: Session, item_id: int, quantity: float, price_per_unit: float,
                   purchased_by: str = None, notes: str = None,
                   supplier_id: int = None, is_credit: bool = False,
                   volume_per_unit: float = None, payment_due_date: str = None,
                   is_opening_stock: bool = False, extra_cost_per_unit: float = 0.0, hisob_id: int = None):
    """Ombor kirimi — xarid narxi bilan (DARHOL commit qiladi — ORQAGA MOSLIK
    uchun saqlangan, hozirgi barcha eski chaqiruvchilar shu funksiyani
    ishlatadi). Ko'p mahsulotli, BITTA tranzaksiya kerak bo'lgan hollarda
    (masalan Ombor Kirim hujjati) — o'rniga _purchase_stock_no_commit()
    ishlatiladi, va commit FAQAT oxirida, bir marta qilinadi."""
    result = _purchase_stock_no_commit(
        db, item_id, quantity, price_per_unit, purchased_by, notes,
        supplier_id, is_credit, volume_per_unit, payment_due_date,
        is_opening_stock, extra_cost_per_unit, hisob_id=hisob_id
    )
    if result is None:
        return None
    db.commit()
    db.refresh(result["item"])
    result["new_price"] = float(result["item"].price_per_unit)
    result["new_volume"] = float(result["item"].volume_per_unit)
    return result


def _purchase_stock_no_commit(db: Session, item_id: int, quantity: float, price_per_unit: float,
                   purchased_by: str = None, notes: str = None,
                   supplier_id: int = None, is_credit: bool = False,
                   volume_per_unit: float = None, payment_due_date: str = None,
                   is_opening_stock: bool = False, extra_cost_per_unit: float = 0.0,
                   company_id: int = None, sana: datetime = None, hisob_id: int = None):
    """Ombor kirimi — xarid narxi bilan. COMMIT QILMAYDI (chaqiruvchi
    o'zi, barcha ishlar tugagach, bitta marta commit qilishi kerak).
    O'rtacha vaznli narx hisoblanadi (eski qoldiq qayta baholanmaydi):

        yangi_narx = (eski_qty × eski_narx + yangi_qty × xarid_narxi) / (eski_qty + yangi_qty)

    Penoplast uchun volume_per_unit (1 blok necha m³) ham partiyadan partiyaga
    farq qilishi mumkin — shu sabab u ham xuddi shu tarzda o'rtacha vaznli hisoblanadi,
    aks holda tan narx/hajm hisob-kitobi noto'g'ri chiqib qoladi.

    is_credit=True bo'lsa — nasiya (keyin to'lash), Supplierga qarz sifatida yoziladi.
    supplier_id — kredit bo'lmasa ham saqlanadi (tarix uchun, "kimdan olganimiz" bilinsin).
    is_opening_stock=True bo'lsa — bu "boshlang'ich (mavjud) ombor" sifatida belgilanadi:
    ombor miqdori/narxi ODATDAGIDEK qo'shiladi, LEKIN Kassa balansi hisobida bu
    "naqd sarflangan pul" deb HISOBLANMAYDI (chunki bu — yangi xarid emas, tizimni
    ishlata boshlashda mavjud xomashyoni hisobga olish).

    extra_cost_per_unit — Ombor Kirim hujjatidagi qo'shimcha xarajatlar (Transport,
    Tushirish, Yuklash, Boshqa) shu material uchun taqsimlangan ulushi (1 birlikka).
    MUHIM: bu, faqat OMBORDAGI O'RTACHA TANNARXni oshirish uchun ishlatiladi —
    InventoryPurchase yozuvidagi price_per_unit/total_amount esa, ASL (tashqi
    hisobot, yetkazib beruvchi qarzi uchun) narxda, o'zgarishsiz qoladi.
    """
    from models import InventoryPurchase

    # 2026-09-21 (12-sizish): company_id berilsa material FAQAT shu
    # korxonadan (aks holda None → chaqiruvchi "Material topilmadi").
    db_item = get_item_locked(db, item_id, company_id)
    if not db_item:
        return None

    old_qty = float(db_item.stock_quantity or 0)
    old_price = float(db_item.price_per_unit or 0)
    old_volume = float(db_item.volume_per_unit or 1.0)

    # O'rtacha tannarx hisoblanadiganda — ASL narx EMAS, "samarali narx"
    # (asl narx + shu birlikka to'g'ri kelgan qo'shimcha xarajat) ishlatiladi.
    effective_price_for_avg = price_per_unit + (extra_cost_per_unit or 0.0)

    total_qty = old_qty + quantity
    if old_qty > 0 and total_qty > 0:
        # Oddiy holat — eski qoldiq HAM ijobiy, shuning uchun to'g'ri,
        # haqiqiy o'rtacha vaznli narxni hisoblaymiz.
        weighted_price = (old_qty * old_price + quantity * effective_price_for_avg) / total_qty
    else:
        # MUHIM (2026-08-18): eski qoldiq MANFIY yoki "0" bo'lsa — eski
        # narxni O'RTACHAGA UMUMAN QO'SHMAYMIZ. Sabab: manfiy miqdorning
        # haqiqiy tannarx asosi yo'q (u — hali kelmagan, "qarzga" ishlatilgan
        # xomashyo). Agar shunday holatda ham eski narxni qo'shsak, natija
        # HAR IKKALA (eski va yangi) narxdan ham chetga chiqib ketardi —
        # masalan -5 dona (785 000 so'm) + 20 dona (900 000 so'm) qo'shilsa,
        # to'g'ri formula 938 333 so'm (ikkalasidan ham QIMMAT!) berardi.
        # Shuning uchun, bunday holatda, faqat YANGI xarid narxi ishlatiladi.
        weighted_price = effective_price_for_avg

    db_item.stock_quantity = total_qty
    db_item.price_per_unit = round(weighted_price, 2)

    volume_changed = False
    if db_item.is_penoplast and volume_per_unit and volume_per_unit > 0:
        if abs(volume_per_unit - old_volume) > 0.001:
            volume_changed = True
        # kech142 (zip 170, A-O06 — O'LCHANGAN `work/audit/tasdiq/ombor/p_o06.py`): blok hajmi ham NARX qoidasi bilan —
        # eski qoldiq MANFIY yoki 0 bo'lsa o'rtachaga KIRMAYDI (yangi partiya hajmi olinadi). Ilgari faqat `total_qty > 0`
        # tekshirilardi: −1 blok (1.0 m³) + 4 blok (1.4 m³) → 1.5333 m³ (ikkala partiyadan ham katta), −3.9 @1.0 + 4 @1.4 →
        # 17.0 m³, −1.9 @1.4 + 2 @1.0 → −6.6 m³ (manfiy hajm — buyurtma penoplastni AYIRISH o'rniga QO'SHARDI).
        if old_qty > 0 and total_qty > 0:
            weighted_volume = (old_qty * old_volume + quantity * volume_per_unit) / total_qty
        else:
            weighted_volume = volume_per_unit
        db_item.volume_per_unit = round(weighted_volume, 4)

    if not db_item.category:
        db_item.category = guess_category(db_item.item_name, db_item.is_penoplast)

    due_date_parsed = None
    if payment_due_date:
        try:
            due_date_parsed = datetime.strptime(payment_due_date, "%Y-%m-%d")
        except (ValueError, TypeError):
            due_date_parsed = None

    # 17g (2026-09-22): narx va jami BAZADAGIDEK yaxlitlanadi — jami SHU
    # (yaxlitlangan) narxdan hisoblanadi (sababi `_xarid_narx_jami` izohida;
    # HAQIQIY PostgreSQL da O'LCHANGAN: 333 × 10.335 → narx 10.34, jami
    # 3441.56). Ombordagi o'rtacha narx hisobiga tegilmaydi.
    _narx2, _jami2 = _xarid_narx_jami(quantity, price_per_unit)
    purchase = InventoryPurchase(
        inventory_id=db_item.id,
        item_name=db_item.item_name,
        quantity=quantity,
        unit=db_item.unit,
        price_per_unit=_narx2,
        total_amount=_jami2,
        purchased_by=purchased_by,
        notes=notes,
        supplier_id=supplier_id,
        is_credit=is_credit,
        category=db_item.category,
        payment_due_date=due_date_parsed,
        is_opening_stock=is_opening_stock,
        extra_cost_per_unit=round(extra_cost_per_unit or 0.0, 4),
        # kech155 (zip 210): faqat naqd (nasiyasiz) xaridda — pul qaysi hisobdan (nasiya / boshlang'ich ombor — pul chiqmaydi)
        hisob_id=(hisob_id if not is_credit and not is_opening_stock else None),
        # kech107 (10f): bekor qilishda narxni AYNAN qaytarish uchun (NULL narx — 0, tizim uni 0 deb hisoblaydi).
        narx_oldin=round(old_price, 2),
        narx_keyin=round(float(db_item.price_per_unit or 0), 2),
        # kech157 (zip 217): penoplast «1 blok necha m³» — bekor qilishda AYNAN qaytarish uchun (boshqa material — NULL)
        hajm_oldin=(round(old_volume, 6) if db_item.is_penoplast else None),
        hajm_keyin=(round(float(db_item.volume_per_unit or 1.0), 6) if db_item.is_penoplast else None)
    )
    # kech115 (G4-03): kirim hujjatida tanlangan o'tgan sana (`kirim_sanalari`) — xarid shu kunga yoziladi (oylik
    # hisobotdagi xomashyo xaridi `purchased_at` bo'yicha). Berilmasa — hozir (ustun standarti).
    if sana is not None:
        purchase.purchased_at = sana
    db.add(purchase)
    supplier_name = None
    if supplier_id:
        from models import Supplier
        sup = db.query(Supplier).filter(Supplier.id == supplier_id).first()
        supplier_name = sup.name if sup else None
    log_movement(
        db, db_item.id, db_item.item_name, movement_type="in",
        quantity=quantity, unit=db_item.unit,
        reason=f"Ta'minotchi: {supplier_name}" if supplier_name else "Xarid",   # kech118 (D-1, U-12): nomlar lug'ati
        supplier_id=supplier_id, performed_by=purchased_by, notes=notes
    )
    db.flush()

    return {
        "item": db_item,
        "purchase": purchase,
        "old_price": old_price,
        "new_price": float(db_item.price_per_unit),
        "old_qty": old_qty,
        "purchase_total": _jami2,
        "old_volume": old_volume,
        "new_volume": float(db_item.volume_per_unit),
        "volume_changed": volume_changed
    }


# kech115 (G4-03): kirim sanasi necha kun orqaga bo'lishi mumkin — kiritishdagi yil xatosi (2025 o'rniga 2052 yoki
# 2025) hisobotni jimgina boshqa yilga surmasin. Kelajak sanasi — rad.
KIRIM_SANA_ORQAGA_KUN = 366


def kirim_sanalari(receipt_date: str = None, payment_due_date: str = None):
    """kech115 (G4-03): kirim hujjatining sanalari — tekshiruv va bazaga yoziladigan qiymat.

    Qaytaradi: (kirim_vaqti, muddat). `kirim_vaqti` — None (bugun yoki berilmagan: hozirgi vaqt, ustun standarti) yoki
    tanlangan O'TGAN kunning 00:00 i (naive; faqat sana kiritiladigan qiymatlar qoidasi — Toshkent kalendarida ham
    o'sha kun: [kun−1 19:00, kun 19:00) UTC). `muddat` — 'YYYY-MM-DD' yoki None. Kun — TOSHKENT kalendari
    (`database.tashkent_date`). Rad (ValueError): noto'g'ri shakl, kelajak sanasi, `KIRIM_SANA_ORQAGA_KUN` dan eski,
    kirim sanasidan oldingi to'lov muddati."""
    from datetime import date as _date_t, timedelta as _td_k

    def _oqi(v, nomi):
        if v is None:
            return None
        if isinstance(v, datetime):
            return v.date()
        if isinstance(v, _date_t):
            return v
        s = str(v).strip()
        if not s:
            return None
        try:
            return datetime.strptime(s[:10], "%Y-%m-%d").date()
        except (ValueError, TypeError):
            raise ValueError(f"{nomi} noto'g'ri: {s[:20]} (kutilgan shakl YYYY-MM-DD)")

    bugun = _tashkent_date()
    kun = _oqi(receipt_date, "Kirim sanasi")
    if kun is not None and kun > bugun:
        raise ValueError(f"Kirim sanasi kelajakda bo'lishi mumkin emas: {kun.strftime('%d.%m.%Y')} "
                         f"(bugun {bugun.strftime('%d.%m.%Y')})")
    if kun is not None and kun < bugun - _td_k(days=KIRIM_SANA_ORQAGA_KUN):
        raise ValueError(f"Kirim sanasi juda eski: {kun.strftime('%d.%m.%Y')} — bir yildan eski sana bilan kirim "
                         f"yozilmaydi, sanani tekshiring")
    muddat = _oqi(payment_due_date, "To'lov muddati")
    if muddat is not None and muddat < (kun or bugun):
        raise ValueError(f"To'lov muddati ({muddat.strftime('%d.%m.%Y')}) kirim sanasidan "
                         f"({(kun or bugun).strftime('%d.%m.%Y')}) oldin bo'lishi mumkin emas")
    kirim_vaqti = None
    if kun is not None and kun != bugun:
        kirim_vaqti = datetime(kun.year, kun.month, kun.day)
    return kirim_vaqti, (muddat.strftime("%Y-%m-%d") if muddat is not None else None)


def kirim_takror_qator(db: Session, items: list, company_id: int = None):
    """kech115 (G4-01): kirim hujjatida AYNAN bir xil qator (material, miqdor, tiyinga yaxlitlangan narx, hajm,
    boshlang'ich belgisi) ikkinchi marta kelsa — ValueError (hech narsa yozilmaydi). Bir materialni BOSHQA narx yoki
    miqdorda olish (ikki partiya — `_takror_material_yoq` izohi) — ruxsat."""
    korilgan = {}
    for i, it in enumerate(items):
        g = it if isinstance(it, dict) else getattr(it, "__dict__", {})
        _miq = float(g.get("quantity") or 0)
        _narx2 = _xarid_narx_jami(_miq, float(g.get("price_per_unit") or 0))[0]
        _hajm = g.get("volume_per_unit")
        kalit = (g.get("inventory_id"), round(_miq, 6), _narx2,
                 (round(float(_hajm), 4) if _hajm else None), bool(g.get("is_opening_stock", False)))
        if kalit in korilgan:
            _nom = None
            try:
                _nq = db.query(Inventory.item_name).filter(Inventory.id == g.get("inventory_id"))
                if company_id is not None:
                    _nq = _nq.filter(Inventory.company_id == company_id)
                _r = _nq.first()
                _nom = _r[0] if _r else None
            except Exception:
                _nom = None
            raise ValueError(
                f"{i + 1}-qator {korilgan[kalit] + 1}-qator bilan AYNAN bir xil"
                + (f" («{_nom}», " if _nom else " (")
                + f"{xabar_son(_miq, 4)} × {xabar_son(_narx2, 2)}"      # kech151 (zip 192): ilgari «12 500.5», «1e+06»
                + ") — takror kiritilgan bo'lishi mumkin. Bittasini o'chiring; ikki partiya bo'lsa miqdorini "
                  "bitta qatorga birlashtiring")
        korilgan[kalit] = i


def create_inventory_receipt(db: Session, items: list, transport_cost: float = 0.0,
                              tushirish_cost: float = 0.0, yuklash_cost: float = 0.0,
                              boshqa_cost: float = 0.0, add_to_cost: bool = False,
                              supplier_id: int = None, document_number: str = None,
                              paid_now: float = 0.0, notes: str = None, created_by: str = None,
                              production_type: str = None, company_id: int = None,
                              receipt_date: str = None, payment_due_date: str = None,
                              yonalish_id=_YON_YOQ, hisob=None) -> dict:
    """Ombor Kirim hujjati — bir nechta mahsulotni, qo'shimcha xarajatlar
    (Transport, Tushirish/Grushchik, Yuklash, Boshqa) bilan birga, BITTA
    yagona tranzaksiya sifatida saqlaydi. Xato bo'lsa — HAMMASI (barcha
    mahsulotlar, barcha xarajatlar) ROLLBACK qilinadi, hech narsa
    yarim-yorti saqlanib qolmaydi.

    items — har biri: {inventory_id, quantity, price_per_unit, volume_per_unit
    (ixtiyoriy), is_opening_stock (ixtiyoriy), notes (ixtiyoriy)}

    add_to_cost=True bo'lsa — 4 ta qo'shimcha xarajat, mahsulotlarning
    QIYMATIGA (quantity × price_per_unit) NISBATAN PROPORSIONAL taqsimlanadi,
    va ombordagi o'rtacha tannarxga qo'shiladi. False bo'lsa — bu xarajatlar
    faqat Moliyada, alohida ko'rinadi, tannarxga ta'sir qilmaydi.

    paid_now — MUHIM: soddalashtirilgan yondashuv (Xomashyo ta'minoti
    sahifasidagi bilan bir xil mantiq). Har bir mahsulot ALOHIDA-ALOHIDA
    qisman to'lov taqsimlanmaydi — barcha mahsulotlar TO'LIQ NASIYA
    (is_credit=True) sifatida yoziladi (agar boshlang'ich ombor bo'lmasa),
    so'ngra, agar paid_now>0 bo'lsa, YAGONA, umumiy SupplierPayment
    yaratiladi — bu, yetkazib beruvchi qarzidan avtomatik ayiriladi.

    SaaS uchun kengaytiriladigan: kelajakda yangi xarajat turi qo'shish uchun,
    shu funksiyaga yangi parametr va extra_costs ro'yxatiga yangi qator
    qo'shish kifoya.

    kech115 (G4-01, G4-03 — O'LCHANGAN `work/k115/probe_kirim.py`, SQLite = PG): (1) AYNAN bir xil qator (material,
    miqdor, narx, hajm, boshlang'ich belgisi) ikki marta kelsa — hech narsa yozilmasdan rad (`kirim_takror_qator`):
    sahifa oxirgi qatorni tekshiruvdan oldin savatga qo'shib, qayta bosishda IKKI marta yuborardi — ombor 200 kg,
    ta'minotchi qarzi 600 000 (100 kg × 3 000 ikki marta). Bir materialni boshqa narxda (ikki partiya) olish —
    avvalgidek mumkin. (2) `receipt_date` — kirim sanasi: o'tgan kun bo'lsa hujjat, xaridlar, qo'shimcha xarajatlar
    va «hozir to'langan» to'lov shu kunga yoziladi (ombor harakati jurnali — kiritilgan vaqtda qoladi); bugun yoki
    bo'sh — hozir. (3) `payment_due_date` — nasiya xaridlarining to'lov muddati (dashboard ogohlantirishi
    `get_supplier_payment_due_dates` shunga tayanadi). Chegaralar — `kirim_sanalari`."""
    from models import InventoryReceipt, ExpenseTransaction, KIRIM_TANNARX_MANBA

    if not items:
        return {"success": False, "error": "Hech qanday mahsulot kiritilmagan"}

    # kech115: HECH NARSA yozilishidan OLDIN — sana chegaralari va takror qator (ValueError → marshrutda 400).
    _kirim_vaqti, _muddat = kirim_sanalari(receipt_date, payment_due_date)
    kirim_takror_qator(db, items, company_id=company_id)
    # kech155 (zip 210): hoziroq to'lov / qo'shimcha xarajatlar / naqd qator qaysi pul hisobidan (noto'g'ri — ValueError, yozuvsiz)
    _hid210 = pul_hisobi_id(db, company_id, hisob=hisob)

    try:
        # M8/F1: `InventoryReceipt`ning yagona ota-FK si (`supplier_id`)
        # NULL bo'lishi mumkin — ta'minotchisiz kirim. U holda model
        # qo'riqchisi korxonani aniqlay olmaydi, shuning uchun tenant
        # ANIQ beriladi. (Ilgari vaqtinchalik `DEFAULT 1` to'ldirardi.)
        # kech117 (A2): kirim yo'nalishi — YAGONA qoida (`yonalish_tanlovi`); kirimning qo'shimcha xarajatlari
        # (pastda, `ExpenseTransaction`) AYNAN shu yo'nalishni oladi. Hech biri berilmasa — «Umumiy».
        _yid_k, _pt_k = yonalish_tanlovi(db, company_id, yonalish_id, production_type)
        if _yid_k is _YON_YOQ:
            _yid_k, _pt_k = None, None
        receipt = InventoryReceipt(
            company_id=company_id,
            supplier_id=supplier_id, document_number=document_number,
            transport_cost=transport_cost or 0, tushirish_cost=tushirish_cost or 0,
            yuklash_cost=yuklash_cost or 0, boshqa_cost=boshqa_cost or 0,
            add_to_cost=add_to_cost, notes=notes, created_by=created_by,
            production_type=_pt_k, yonalish_id=_yid_k
        )
        if _kirim_vaqti is not None:          # kech115 (G4-03): tanlangan o'tgan sana
            receipt.receipt_date = _kirim_vaqti
        db.add(receipt)
        db.flush()  # receipt.id kerak bo'ladi

        total_extra = float(transport_cost or 0) + float(tushirish_cost or 0) + \
                      float(yuklash_cost or 0) + float(boshqa_cost or 0)

        # Barcha mahsulotlarning BAZA (xomashyoning o'zi) qiymati — proporsional
        # taqsimlash uchun "og'irlik" sifatida ishlatiladi.
        items_total_value = sum(float(it["quantity"]) * float(it["price_per_unit"]) for it in items)

        created_results = []
        purchase_ids = []
        # kech146 (zip 180, mustaqil tekshiruv — ESKI xato, O'LCHANGAN HAQIQIY PG 16): hujjat materiallari id TARTIBIDA oldindan
        # qulflanadi (har qator keyin o'z qulfini qayta oladi — `_purchase_stock_no_commit`). Ilgari qator tartibida qulflanardi: bir xil
        # ikki materialli ikki Kirim (qatorlari teskari tartibda) parallel yaratilsa — deadlock 40P01, biri 500 «Kirim saqlanmadi».
        # Bekor qilish (`kirim_hujjatini_bekor_qilish`) ham shu tartibda qulflaydi.
        for _iid146 in sorted({int(it["inventory_id"]) for it in items if it.get("inventory_id")}):
            get_item_locked(db, _iid146, company_id)
        for it in items:
            base_value = float(it["quantity"]) * float(it["price_per_unit"])
            extra_share = 0.0
            if add_to_cost and total_extra > 0 and items_total_value > 0:
                extra_share = total_extra * (base_value / items_total_value)
            extra_per_unit = (extra_share / float(it["quantity"])) if float(it["quantity"]) > 0 else 0.0

            is_opening = bool(it.get("is_opening_stock", False))
            # Boshlang'ich ombor bo'lmasa — HAMMASI, soddalik uchun, to'liq
            # nasiya sifatida yoziladi (pastda, yagona to'lov ayiriladi).
            item_is_credit = (not is_opening) and bool(supplier_id)

            result = _purchase_stock_no_commit(
                db, it["inventory_id"], float(it["quantity"]), float(it["price_per_unit"]),
                purchased_by=created_by, notes=it.get("notes") or notes,
                supplier_id=supplier_id, is_credit=item_is_credit,
                volume_per_unit=it.get("volume_per_unit"),
                # kech115 (G4-03): hujjat muddati — faqat nasiyaga yoziladigan qatorda (boshlang'ich ombor /
                # ta'minotchisiz qatorning qarzi yo'q, muddati ogohlantirish bermasin).
                payment_due_date=(_muddat if item_is_credit else None),
                is_opening_stock=is_opening,
                extra_cost_per_unit=extra_per_unit,
                company_id=company_id,
                sana=_kirim_vaqti,
                hisob_id=_hid210,
            )
            if result is None:
                raise ValueError(f"Material topilmadi (id={it['inventory_id']})")

            result["purchase"].receipt_id = receipt.id
            created_results.append(result)
            purchase_ids.append(result["purchase"].id)

        # 4 ta qo'shimcha xarajat turini, Moliyada ALOHIDA ko'rinishi uchun,
        # ExpenseTransaction sifatida yozamiz (add_to_cost holatidan qat'i
        # nazar — bu, "qancha transportga ketdi" kabi statistik ko'rinish
        # uchun). kech87 (104-band, O'LCHANGAN): ilgari "tannarxga qo'shish" bilan yozilgan xarajat sof
        # foydadan HAM ayrilardi (bir marta shu yozuv orqali, yana bir marta xomashyo tannarxi orqali) —
        # endi bunday yozuv `source = KIRIM_TANNARX_MANBA` bilan belgilanadi va oylik hisobot uni sof
        # foydaga alohida qo'shmaydi (Moliyada ko'rinishi saqlanadi).
        # MUHIM: agar BUTUN hujjatdagi barcha mahsulotlar "Ombordagi mavjud
        # xomashyo" (boshlang'ich ombor) deb belgilangan bo'lsa — bu haqiqiy
        # xarid/tranzaksiya EMAS, shunchaki mavjud zaxirani tizimga kiritish.
        # Shu sabab, qo'shimcha xarajatlar (Transport/Tushirish/Yuklash/
        # Boshqa) ham — xomashyoning o'zi kabi — Moliyada xarajat sifatida
        # YOZILMAYDI. Agar hujjatda aralash (ba'zisi yangi xarid, ba'zisi
        # boshlang'ich ombor) bo'lsa — xavfsizlik uchun, xarajatlar odatdagidek
        # yoziladi (chunki hujjatning bir qismi haqiqiy xarid hisoblanadi).
        all_opening_stock = all(bool(it.get("is_opening_stock", False)) for it in items)
        # kech87 (104-band): xarajat haqiqatan tannarxga qo'shildimi — yuqoridagi `extra_share` sharti bilan
        # AYNAN bir xil (qo'shilmagan bo'lsa — oddiy xarajat, sof foydadan ayriladi).
        _tannarxga = bool(add_to_cost and total_extra > 0 and items_total_value > 0)

        cost_categories = [
            ("transport_kirim", transport_cost, "Transport (kirim)"),
            ("tushirish_kirim", tushirish_cost, "Tushirish (Grushchik)"),
            ("yuklash_kirim", yuklash_cost, "Yuklash"),
            ("kirim_boshqa", boshqa_cost, "Boshqa xarajat (kirim)"),
        ]
        if not all_opening_stock:
            for cat, amount, label in cost_categories:
                amount = float(amount or 0)
                if amount <= 0:
                    continue
                # M8/F1: `ExpenseTransaction` tenant ildiz modeli — ota-zanjiri
                # yo'q, shuning uchun `company_id` ANIQ berilishi SHART
                # (ilgari vaqtinchalik `DEFAULT 1` uni to'ldirardi).
                tx = ExpenseTransaction(
                    company_id=company_id,
                    date=receipt.receipt_date, category=cat, amount=amount,
                    notes=f"{label} — Kirim #{receipt.id}" + (f" ({document_number})" if document_number else ""),
                    created_by=created_by,
                    source=(KIRIM_TANNARX_MANBA if _tannarxga else "inventory_receipt"),
                    production_type=_pt_k, yonalish_id=_yid_k,
                    hisob_id=_hid210,                       # kech155 (zip 210)
                )
                db.add(tx)

        # Yagona, umumiy to'lov (agar kiritilgan bo'lsa)
        payment_created = None
        if paid_now and float(paid_now) > 0 and supplier_id:
            from models import SupplierPayment
            payment_created = SupplierPayment(
                supplier_id=supplier_id, amount=float(paid_now),
                paid_by=created_by, hisob_id=_hid210,       # kech155 (zip 210)
                notes=f"Kirim to'lovi — #{receipt.id}" + (f" ({document_number})" if document_number else "")
            )
            if _kirim_vaqti is not None:      # kech115 (G4-03): to'lov kirim kunida
                payment_created.paid_at = _kirim_vaqti
            db.add(payment_created)

        db.commit()
        db.refresh(receipt)

        return {
            "success": True,
            "receipt_id": receipt.id,
            "purchase_ids": purchase_ids,
            "items_total_value": round(items_total_value),
            "total_extra_cost": round(total_extra),
            "add_to_cost": add_to_cost,
            "paid_now": float(paid_now or 0),
            "results": [{"item_id": r["item"].id, "item_name": r["item"].item_name,
                         "old_price": r["old_price"], "new_price": r["new_price"]} for r in created_results]
        }
    except Exception:
        db.rollback()
        raise


def material_ishlatilganmi(db: Session, item, jadvallar=None) -> bool:
    """kech158 (zip 218 — egasi tanlovi 26.10 «1 va 2 ni tuzatish»): material ISHLATILGANmi — qoldig'i 0 emas yoki `inventory.id` ga
    bog'langan biror jadvalda (ombor harakati, xarid, kirim hujjati qatori, loy retsepti, ishlab chiqarish retsepti (BOM), buyurtma detali
    plotnosti, tayyor mahsulot, qaytarish …) yozuv bor. Jadvallar ro'yxati qo'lda emas — `models.Base.metadata` dagi tashqi kalitlardan
    (yangi jadval o'zi qo'shiladi; `delete_item` ning «tarixi bor — yashiriladi» qoidasi bilan bir ma'no). `jadvallar` — faqat shu nomli
    jadvallar (masalan `("bom_items",)`), qoldiq hisobga olinmaydi."""
    from sqlalchemy import select as _sel218, literal as _lit218
    from models import Base as _Base218
    try:
        import importlib as _il218
        _il218.import_module("production_models")     # retsept (BOM) jadvallari metadata da bo'lsin
    except ImportError:          # pragma: no cover
        pass
    if jadvallar is None and abs(float(item.stock_quantity or 0)) > 1e-9:
        return True
    if jadvallar is None and _surat_ishlatadimi218(db, item):
        return True
    for _t in list(_Base218.metadata.tables.values()):     # tartib kerak emas (`sorted_tables` — tsikl ogohlantirishi beradi)
        if _t.name == Inventory.__tablename__ or (jadvallar is not None and _t.name not in jadvallar):
            continue
        for _fk in _t.foreign_keys:
            if _fk.column.table.name != Inventory.__tablename__ or _fk.column.name != "id":
                continue
            if db.execute(_sel218(_lit218(1)).select_from(_t).where(_fk.parent == item.id).limit(1)).first() is not None:
                return True
    return False


def _surat_ishlatadimi218(db: Session, item) -> bool:
    """kech158 (zip 218, review218 №6): boshlangan (IN_PROGRESS) ishlab chiqarish buyurtmasining retsept SURATIDA (`recipe_snapshot_json`
    — qatorlar ro'yxati, har birida `inventory_id`) shu material bormi. Retsept qatori keyin o'chirilgan bo'lsa ham «Yakunlash» suratdagi
    miqdorni OMBOR birligida yechadi — birlik o'zgarsa ma'nosi buziladi. Boshqa holatlar: DRAFT — surat yo'q, COMPLETED — ombor harakati bor."""
    import json as _json218
    try:
        import importlib as _il218s
        _pm218 = _il218s.import_module("production_models")
    except ImportError:          # pragma: no cover
        return False
    _PO = _pm218.ProductionOrder
    _q = db.query(_PO.recipe_snapshot_json).filter(_PO.company_id == item.company_id,
                                                   _PO.status == _pm218.ProductionOrderStatus.IN_PROGRESS.value,
                                                   _PO.recipe_snapshot_json.isnot(None))
    for (_js,) in _q:
        try:
            _qatorlar = _json218.loads(_js or "[]")
        except (TypeError, ValueError):
            continue
        for _l in (_qatorlar if isinstance(_qatorlar, list) else []):
            if isinstance(_l, dict) and str(_l.get("inventory_id")) == str(item.id):
                return True
    return False


def _retsept_birligi218(unit, base_unit, conversion_factor) -> str:
    """kech158 (zip 218): ishlab chiqarish retseptidagi (BOM) miqdor qaysi birlikda o'qiladi — `production_models.BOMItem.unit` va
    `production_service._compute_bom_line` bilan BIR qoida: mayda birlik VA koeffitsient bo'lsa — mayda birlik, aks holda ombor birligi."""
    return str((base_unit if (base_unit and conversion_factor) else unit) or "").strip()


def update_item(db: Session, item_id: int, item_data: InventoryUpdate) -> Optional[Inventory]:
    """Xomashyo ma'lumotlarini yangilaydi."""
    db_item = get_item(db, item_id)
    if not db_item:
        return None
    update_data = item_data.model_dump(exclude_unset=True)
    # 14-band: qat'iy tekshiruv — HECH NARSA yozilmasdan OLDIN (ValueError → 400).
    update_data = _clean_update("Inventory", update_data)
    # Asosiy penoplast "penoplast emas" deb belgilansa, `default_id`
    # penoplast bo'lmagan materialga ishora qilib qoladi.
    if update_data.get("is_penoplast") is False and db_item.is_default_penoplast:
        raise ValueError("Asosiy penoplastni oddiy materialga aylantirib bo'lmaydi — "
                         "avval boshqa penoplastni asosiy qiling")
    # kech112 (K112-4, O'LCHANGAN — `work/k113/probe_nom.py`, SQLite = PG; jonli C zanjiri sizish tekshiruvida topildi):
    # materialni shu korxonadagi BOSHQA material nomiga qayta nomlash `uq_inventory_company_item_name` ga urilib
    # 500 ("Serverda kutilmagan xato") va xato jurnaliga yozuv berardi; nom bo'shliqlari bilan ("Akril ") saqlanardi.
    # Endi: nom chetidagi bo'shliqlarsiz; bo'sh — rad; boshqa material (yashirilgani ham — u nomni band qiladi) shu
    # nomda bo'lsa — hech narsa yozilmasdan 400 (yaratishdagi "allaqachon mavjud" xabari kabi).
    if "item_name" in update_data and update_data["item_name"] is not None:
        _yangi_nom = str(update_data["item_name"]).strip()
        if len(_yangi_nom) < 2:
            raise ValueError("Material nomi kamida 2 belgi bo'lishi kerak")
        update_data["item_name"] = _yangi_nom
        if _yangi_nom != db_item.item_name:
            # kech159 (zip 219, L4 / L3): mavjud retseptning ortgan loy zaxirasi — nomi retsept nomidan (o'zgartirilsa zaxira retseptdan
            # uziladi, retsept yangi bo'sh zaxira yaratadi); boshqa material «Tayyor loy (…)» nomini olmaydi
            _r219 = loy_zaxirasi_retsepti(db, db_item)
            if _r219 is not None:
                raise ValueError(f"«{db_item.item_name}» — «{_r219.name}» retseptining ortgan loy zaxirasi: nomi retsept nomidan olinadi, "
                                 f"uni o'zgartirib bo'lmaydi (retsept nomi «Loy retseptlari» da o'zgartirilsa — zaxira nomi o'zi o'zgaradi)")
            if loy_zaxira_nomimi(_yangi_nom):
                raise ValueError(LOY_ZAXIRA_NOMI_XATO)
            # kech143 (zip 171, N1): nom KALITI bo'yicha (harf / bo'shliq / apostrof farqi — boshqa materialning nomi); o'z nomining
            # yozilishini o'zgartirish («akril» → «Akril») — ruxsat. PG da korxona bo'yicha qulf (yaratish bilan bir fazo).
            _pul_qulfi(db, MATERIAL_NOMI_QULF_NS, db_item.company_id or 0)
            _band = next(iter(nomdosh_materiallar(db, db_item.company_id, _yangi_nom, istisno_id=db_item.id)), None)
            if _band is not None:
                _x143 = "" if _band.item_name == _yangi_nom else f' («{_band.item_name}»)'
                if _band.is_deleted:
                    raise ValueError(f'"{_yangi_nom}" nomi avval o\'chirilgan (yashirilgan) materialda band{_x143} — '
                                     f'boshqa nom tanlang')
                raise ValueError(f'"{_yangi_nom}" nomli material allaqachon omborda mavjud{_x143} — boshqa nom tanlang')
    # kech142 (zip 170, A-O10 c): mayda birlik — koeffitsient bilan (NATIJAVIY holat: koeffitsient o'chirilib mayda birlik
    # qolsa ham, oddiy materialga koeffitsientsiz mayda birlik berilsa ham — rad, hech narsa yozilmaydi). Faqat birlik /
    # mayda birlik / koeffitsient o'zgartirilganda — eski (koeffitsientsiz) materialning boshqa tahriri (nom, minimal qoldiq)
    # to'silmaydi.
    if any(k in update_data for k in ("unit", "base_unit", "conversion_factor")):
        _bx = _birlik_ogirish_xatosi(update_data["unit"] if "unit" in update_data else db_item.unit,
                                     update_data["base_unit"] if "base_unit" in update_data else db_item.base_unit,
                                     update_data["conversion_factor"] if "conversion_factor" in update_data
                                     else db_item.conversion_factor)
        if _bx:
            raise ValueError(_bx)
    # kech158 (zip 218 — egasi tanlovi 26.10 «1 va 2 ni tuzatish (Tavsiya)»; O'LCHANGAN `work/k218/probe218a.py`, SQLite = PG): tarixi bor
    # materialda birlik / tur jimgina o'zgarardi — 50 kg kirim, 10 kg chiqim qilingan «Akril» «litr» qilinsa qoldiq «40 litr», tarix «kg»;
    # oddiy material penoplastga (va aksincha) aylanardi. Endi ISHLATILGAN materialda (`material_ishlatilganmi`) — 400, hech narsa yozilmaydi;
    # retseptda (BOM) bo'lsa retsept birligi ham o'zgarmaydi (koeffitsient sonini tuzatish — ruxsat). Tarixsiz material — avvalgidek.
    # kech159 (zip 219): retseptning ortgan loy zaxirasi — har doim kg va oddiy material (`get_or_create_loy_stock`; ortgan loy kg da
    # qo'shiladi, buyurtma kg da oladi) — tarixi bo'lmasa ham birligi / turi o'zgarmaydi
    if (("unit" in update_data and update_data["unit"] is not None
         and str(update_data["unit"]).strip() != str(db_item.unit or "").strip())
            or update_data.get("is_penoplast") is True) and loy_zaxirasi_retsepti(db, db_item) is not None:
        raise ValueError(f"«{db_item.item_name}» — ortgan loy zaxirasi: birligi «{db_item.unit}» va turi (oddiy material) o'zgarmaydi")
    if any(k in update_data for k in ("unit", "is_penoplast", "base_unit", "conversion_factor")):
        # review218 №5 (O'LCHANGAN PG, kechiktirish bilan): `create_bom` navbatsiz — oddiy `FOR UPDATE` uning KEY SHARE qulfini kutadi /
        # to'xtatadi; rad etilsa marshrut `rollback` qiladi (qulf darhol bo'shaydi)
        db_item = inventory_qulf(db, db_item.id, ochirish=True) or db_item
    _eski_birlik = str(db_item.unit or "").strip()
    _yangi_birlik = str(update_data["unit"]).strip() if update_data.get("unit") is not None else _eski_birlik
    _birlik_ozgardi = _yangi_birlik != _eski_birlik
    if update_data.get("unit") is not None:
        if _birlik_ozgardi:
            update_data["unit"] = _yangi_birlik     # chetdagi bo'shliqlarsiz (nom kabi)
        else:
            update_data.pop("unit")                 # faqat bo'shliq farqi — o'zgarish emas, yozilmaydi (« kg » tarixdagi «kg» dan farq qilmasin)
    _tur_ozgardi = "is_penoplast" in update_data and bool(update_data["is_penoplast"]) != bool(db_item.is_penoplast)
    _ish218 = None
    if _birlik_ozgardi or _tur_ozgardi:
        _ish218 = material_ishlatilganmi(db, db_item)
    if _ish218 and _birlik_ozgardi:
        raise ValueError(f"«{db_item.item_name}» allaqachon ishlatilgan (qoldiq, kirim / chiqim, retsept yoki buyurtma yozuvlari bor) — "
                         f"birligini «{_eski_birlik}» dan «{_yangi_birlik}» ga o'zgartirib bo'lmaydi: eski yozuvlardagi miqdorlar "
                         f"«{_eski_birlik}» da. Boshqa birlik kerak bo'lsa — yangi material yarating")
    if _ish218 and _tur_ozgardi:
        _qayer = "penoplastni oddiy materialga" if db_item.is_penoplast else "oddiy materialni penoplastga (plotnost)"
        raise ValueError(f"«{db_item.item_name}» allaqachon ishlatilgan (qoldiq, kirim / chiqim, retsept yoki buyurtma yozuvlari bor) — "
                         f"{_qayer} aylantirib bo'lmaydi: eski yozuvlar shu turga bog'langan. Kerak bo'lsa — yangi material yarating")
    if any(k in update_data for k in ("unit", "base_unit", "conversion_factor")):
        _rb_eski = _retsept_birligi218(db_item.unit, db_item.base_unit, db_item.conversion_factor)
        _rb_yangi = _retsept_birligi218(update_data["unit"] if "unit" in update_data else db_item.unit,
                                        update_data["base_unit"] if "base_unit" in update_data else db_item.base_unit,
                                        update_data["conversion_factor"] if "conversion_factor" in update_data
                                        else db_item.conversion_factor)
        if _rb_eski != _rb_yangi and material_ishlatilganmi(db, db_item, jadvallar=("bom_items",)):
            raise ValueError(f"«{db_item.item_name}» ishlab chiqarish retseptlarida ishlatilgan — retsept birligi «{_rb_eski}» dan "
                             f"«{_rb_yangi}» ga o'zgarib, retseptdagi miqdorlar «{_rb_yangi}» deb o'qilib ketadi. Avval retseptlardagi "
                             f"qatorlarni o'zgartiring yoki yangi material yarating")
    for field, value in update_data.items():
        setattr(db_item, field, value)
    db.commit()
    db.refresh(db_item)
    return db_item


class MaterialQoldiqBor(ValueError):
    """kech142 (zip 170 — EGASI QARORI 12.10 «O'chirishdan oldin 0 bo'lsin»): qoldig'i 0 bo'lmagan material o'chirilmaydi —
    marshrut 409, sababi bilan (avval qoldiq «Chiqim (tuzatish)» / «Kirim (tuzatish)» bilan 0 qilinadi — jurnalda
    ko'rinadi)."""


def material_qoldiq_xabari(m) -> str:
    """kech142 (zip 170): qoldig'i bor materialni o'chirish rad xabari (server va sahifa — bir xil ma'no)."""
    q = float(m.stock_quantity or 0)
    _q = _miqdor_matn(q)   # kech152 (zip 193): sahifadagi `sonKor(qoldiq, 3)` bilan bir ko'rinish (ilgari «1234.5»)
    if q < 0:
        return (f"«{m.item_name}» qoldig'i manfiy ({_q} {m.unit or ''}) — o'chirishdan oldin «Kirim (tuzatish)» bilan "
                f"qoldiqni 0 qiling (tuzatish ombor harakatlarida ko'rinadi)")
    return (f"«{m.item_name}» omborda hali {_q} {m.unit or ''} bor — o'chirishdan oldin «Chiqim (tuzatish)» bilan "
            f"qoldiqni 0 qiling (tuzatish ombor harakatlarida ko'rinadi)")


def delete_item(db: Session, item_id: int) -> dict:
    """Xomashyoni o'chiradi.
    Agar bu xomashyo biror buyurtma/harakat/xarid tarixida ISHLATILGAN bo'lsa —
    bazadan butunlay o'chirib bo'lmaydi (eski hisobotlar buziladi). Shunday holatda
    XAVFSIZ tarzda 'yumshoq o'chirish' qilinadi — Omborxona ro'yxatidan yo'qoladi,
    lekin eski buyurtmalarda ko'rinishda davom etadi.

    kech142 (zip 170 — EGASI QARORI 12.10 «O'chirishdan oldin 0 bo'lsin»): qoldig'i 0 bo'lmagan material o'chirilmaydi
    (`MaterialQoldiqBor` → 409). Ilgari qoldiq bilan jimgina yashirilardi — o'sha qoldiq hech qayerda ko'rinmas, nom
    qayta yaratilganda esa ustidan yozilib yo'qolardi (A-O09). Endi qoldiq avval tuzatish bilan 0 qilinadi (jurnalda
    ko'rinadi), so'ng o'chiriladi. Qoldiq QULF ostida o'qiladi (parallel kirim bilan poyga bo'lmasin)."""
    from sqlalchemy.exc import IntegrityError, ProgrammingError

    db_item = inventory_qulf(db, item_id, ochirish=True)     # kech155 (zip 199): qator o'chiriladi — `FOR UPDATE`
    if not db_item:
        return {"success": False, "message": "Xomashyo topilmadi"}

    # kech37 (18-band, K37-1 — O'LCHANGAN, asl kod): asosiy penoplast bemalol
    # o'chirilardi (200). Keyin korxonada "★ Asosiy" belgili penoplast qolmasdi,
    # `/api/penoplasts` `default_id` esa tasodifiy qolgan penoplastga tushardi; PG da
    # (tarixi bor → YASHIRILADI) yashirin qator `is_default_penoplast = True` ni
    # saqlagani uchun keyin yaratilgan penoplast ham asosiy bo'lmasdi. Endi
    # `update_item` / `add_item` dagi qoida bilan bir xil: boshqa ko'rinadigan
    # penoplast bo'lsa — rad ("avval boshqa penoplastni asosiy qiling"); yagona
    # penoplast bo'lsa — o'chiriladi / yashiriladi va belgisi olib tashlanadi
    # (keyingi yangi penoplast avtomatik asosiy bo'ladi).
    if db_item.is_default_penoplast:
        _boshqa_peno = db.query(Inventory).filter(
            Inventory.company_id == db_item.company_id,
            Inventory.id != db_item.id,
            Inventory.is_penoplast == True,
            Inventory.is_deleted.isnot(True)
        ).first()
        if _boshqa_peno:
            raise ValueError("Asosiy penoplastni o'chirib bo'lmaydi — avval boshqa penoplastni "
                             "asosiy qiling (\"☆ Asosiy qilish\" tugmasi)")
    # kech142 (zip 170 — egasi qarori): qoldiq tekshiruvi asosiy penoplast qoidasidan KEYIN — avval tuzilma sababi (boshqa
    # penoplastni asosiy qilish), so'ng qoldiq (foydalanuvchi qoldiqni behuda 0 qilib, keyin baribir o'chira olmay qolmasin).
    if abs(float(db_item.stock_quantity or 0)) > 1e-9:
        raise MaterialQoldiqBor(material_qoldiq_xabari(db_item))

    try:
        db.delete(db_item)
        db.commit()
        return {"success": True, "soft": False, "message": "Xomashyo butunlay o'chirildi"}
    except (IntegrityError, ProgrammingError):
        db.rollback()
        # kech142 (zip 170): rollback qulfni bo'shatdi — qator QAYTA qulflanib, qoldiq yana tekshiriladi (shu orada kirim
        # qilingan bo'lsa — qoldiqli material yashirilmasin).
        db_item = inventory_qulf(db, item_id, ochirish=True)
        if not db_item:
            return {"success": False, "message": "Xomashyo topilmadi"}
        if abs(float(db_item.stock_quantity or 0)) > 1e-9:
            raise MaterialQoldiqBor(material_qoldiq_xabari(db_item))
        db_item.is_deleted = True
        # kech37 (18-band): yashirilgan qator asosiy penoplast bo'lib QOLMAYDI
        db_item.is_default_penoplast = False
        db.commit()
        return {
            "success": True, "soft": True,
            "message": "Bu xomashyo eski buyurtma/harakatlarda ishlatilgan — butunlay o'chirib bo'lmadi. "
                       "Shuning uchun ro'yxatdan YASHIRILDI (eski hisobotlar buzilmasligi uchun)."
        }


def kam_qoldiq_sharti():
    """kech108 (K108-2, 19-band — EGASI QARORI "Ha, ko'rinsin"): "kam qolgan xomashyo" ning YAGONA sharti.

    Qoldiq ≤ minimal qoldiq; minimal qoldiq belgilanmagan (0 / NULL) bo'lsa — 0: TUGAGAN material (qoldiq ≤ 0) ham
    "kam" (qo'ng'iroqcha «qolmadi» va Omborxona «Kam qolganlar» bilan bir xil). Yashirilgan (`is_deleted`) material va
    "Tayyor loy (" zaxirasi (kech36 / kech37 21-band qarori — ortgan loy uchun chegara yo'q) — hech qachon.
    Ilgari uch xil qoida bor edi (O'LCHANGAN — `main` ning haqiqiy ma'lumotida Penoplast 10P −0.06 / 0: KPI va
    qo'ng'iroqcha "tugagan", bosh sahifa "Barcha xomashyo yetarli"). Ishlatiladi: `get_low_stock_items` (Telegram
    ogohlantirishlari), `services.check_low_stock` (bosh sahifa, dashboard, buyurtmalar sahifasi, bugungi vazifalar,
    grafik), `services.get_business_alerts` (hisobotlar); `services.get_inventory_kpi` va `main.api_full_stock_report`
    — xuddi shu qoida Python da (`kam_qoldiqmi`)."""
    from sqlalchemy import func as _f
    return (Inventory.is_deleted.isnot(True),
            _f.coalesce(Inventory.stock_quantity, 0) <= _f.coalesce(Inventory.min_stock, 0),
            ~Inventory.item_name.like('Tayyor loy (%'))


def kam_qoldiqmi(item) -> bool:
    """`kam_qoldiq_sharti` ning Python nusxasi (bitta obyekt uchun) — AYNAN o'sha qoida."""
    if getattr(item, "is_deleted", False):
        return False
    if str(getattr(item, "item_name", "") or "").startswith("Tayyor loy ("):
        return False
    return float(getattr(item, "stock_quantity", 0) or 0) <= float(getattr(item, "min_stock", 0) or 0)


def get_low_stock_items(db: Session, company_id: int = None) -> List[Inventory]:
    """Qoldiq min_stock dan kam bo'lgan xomashyolar (ogohlantirish).

    MUHIM: "Tayyor loy (...)" yozuvlari — bu, sotib olinadigan xomashyo
    EMAS, balki buyurtmalardan ORTGAN, avtomatik yaratiladigan zaxira
    (get_or_create_loy_stock orqali). U, tabiiy ravishda, to'liq
    ishlatilib, aniq "0"ga tushishi — kutilgan, normal holat (xarid
    qilish kerak degani EMAS). Shuning uchun, bu turkum, "kam qoldi"
    ogohlantirishidan chiqarib tashlanadi — ombordagi haqiqiy miqdorning
    o'ziga (va keyingi buyurtmalar uchun ishlatilishiga) bu SIRA tegmaydi.
    """
    # 2026-09-22 (kech34, K34-1): yashirilgan (o'chirilgan) material Telegram
    # "kam qoldi" xabarlariga (qo'lda ogohlantirish, kunlik cron, buyurtma va
    # ishlab chiqarishdan keyingi ogohlantirish) tushmaydi.
    # kech108 (K108-2): YAGONA shart — `kam_qoldiq_sharti` (NULL min / qoldiq — 0)
    q = db.query(Inventory).filter(*kam_qoldiq_sharti())
    # 2026-09-21: QAT'IY filtr — korxona noma'lum (None) bo'lsa bo'sh ro'yxat
    # (`company_id IS NULL` hech narsa topmaydi). Ilgari shartli edi: None da
    # BARCHA korxonalarning kam qolgan xomashyosi qaytib, Telegram xabariga
    # aralashib ketardi (4 marshrut korxonasiz chaqirardi).
    q = q.filter(Inventory.company_id == company_id)
    return q.all()


