def _takror_material_yoq(qatorlar, kalit: str, ro_yxat_nomi: str,
                         nima: str = "material"):
    """17b (2026-09-21): bitta materialni ro'yxatda IKKI MARTA ko'rsatishni
    rad etadi.

    Retseptda bu ANIQ xato: `services.deduct_loy_ingredients` har qatorni
    alohida ayiradi, ya'ni bir material ikki qatorda bo'lsa ombordan IKKI
    BARAVAR yechiladi, retsept oynasida esa bu ikki alohida qator bo'lib
    ko'rinadi (o'lchandi: 200 va ikkala qator ham saqlanardi).

    ⚠ Kirim HUJJATIDA (`Receipt`) bu ATAYLAB tekshirilmaydi: bir xil
    materialni bitta hujjatda ikki xil narxda olish MUMKIN (ikki partiya),
    va har qator o'z o'rtacha narxini to'g'ri hisoblaydi."""
    korilgan = set()
    for i, q in enumerate(qatorlar):
        v = q.get(kalit) if isinstance(q, dict) else getattr(q, kalit, None)
        if v in korilgan:
            raise ValueError(f"'{ro_yxat_nomi}' {i + 1}-qator: bu {nima} "
                             f"ro'yxatda allaqachon bor")
        korilgan.add(v)


def _clean_val(model: str, data) -> dict:
    """17-band tanasini QAT'IY tekshiradi va tozalangan nusxasini qaytaradi.
    `data` — xom JSON (marshrut) yoki `model_dump(exclude_unset=True)`
    (crud ildizi). Noma'lum kalit, noto'g'ri tur, NaN / cheksizlik, manfiy
    yoki chegaradan katta son, ustun sig'imidan uzun matn, noto'g'ri tanlov —
    `ValueError` (marshrut → 400), hech narsa yozilmaydi."""
    toza = _clean_by_rules(_val_rules()[model], {}, data, "Noma'lum maydon: ")
    for key, eng_kam in _VAL_MAJBURIY.get(model, {}).items():
        if toza.get(key) is None:
            raise ValueError(f"'{key}' kiritilishi shart")
        if eng_kam and len(toza[key].strip()) < eng_kam:
            raise ValueError(f"'{key}' kamida {eng_kam} belgidan iborat bo'lishi kerak")
    # 17b: retsept tarkibida bir material IKKI MARTA bo'lmasin (kirim
    # hujjatida — ataylab RUXSAT, sababi `_takror_material_yoq` izohida).
    if model == "RecipeBody":
        _takror_material_yoq(toza.get("ingredients") or [], "inventory_id",
                             "ingredients")
    # 17g (kech25, 2026-09-22): yetkazishda BIR detal ikki qatorda bo'lmasin.
    # O'LCHANGAN (asl kod = 17f va 17g WIP): 10 metrlik detal [6, 6] qatorlar
    # bilan berilganda 200 qaytib, 12 metr topshirilgan deb yozilardi —
    # `create_delivery` har qatorni detalning bazadagi qoldig'i bilan ALOHIDA
    # solishtiradi (shu so'rovdagi boshqa qatorlarni hisobga olmaydi).
    # `orders.html` har detalni bir marta yuboradi; servis ("Tayyor")
    # ham har detal uchun bitta qator tuzadi.
    if model == "Delivery":
        _takror_material_yoq(toza.get("items") or [], "order_item_id", "items",
                             nima="detal")
    # 17b: miqdor va narx ALOHIDA chegaradan o'tsa ham, KO'PAYTMASI
    # `InventoryPurchase.total_amount` (Numeric(12,2)) sig'imidan oshishi
    # mumkin (o'lchandi: 1e9 × 1e6 = 1e15 → 200, PostgreSQL da COMMIT da
    # 500). Shuning uchun jami summa ham tekshiriladi.
    if model in ("Purchase", "ReceiptItem"):
        _miq, _nar = toza.get("quantity"), toza.get("price_per_unit")
        if _miq is not None and _nar is not None:
            # 17g: jami bazaga YAXLITLANGAN narxdan hisoblanib yoziladi
            # (`_xarid_narx_jami`), shuning uchun sig'im ham SHU jamiga
            # nisbatan tekshiriladi — xom ko'paytma sig'im ichida bo'lsa-da,
            # yaxlitlangan narx bilan oshib ketishi mumkin (2 ×
            # 4 999 999 999.995 → narx 5 000 000 000.00, jami 10 000 000 000.00).
            if _miq * _nar > _ORDER_ITEM_MAX_MONEY or \
                    _xarid_narx_jami(_miq, _nar)[1] > _ORDER_ITEM_MAX_MONEY:
                raise ValueError("'quantity' × 'price_per_unit' juda katta "
                                 "(jami summa sig'imdan oshdi)")
    # 17f: 0 ruxsat etilgan, lekin hosila yozuv yaratadigan pul maydonlari —
    # 0 yoki kamida 1 tiyin (sababi `_NOL_YOKI_TIYIN` izohida).
    for _nk in _NOL_YOKI_TIYIN.get(model, ()):
        _nv = toza.get(_nk)
        if _nv is not None and _nv > 0 and round(_nv, 2) < _PUL_ENG_KAM:
            raise ValueError(f"'{_nk}' 0 yoki kamida {_PUL_ENG_KAM} bo'lishi kerak "
                             "(1 tiyindan kichik summa bazada 0 ga aylanadi)")
    # 17b: "sana" qoidasi matnni `datetime` ga o'giradi, lekin bu yo'lda
    # `schemas.StockPurchase.payment_due_date` — MATN (`Optional[str]`) va
    # `_purchase_stock_no_commit` uni `strptime(..., "%Y-%m-%d")` bilan
    # o'qiydi. Shuning uchun tekshiruvdan keyin AYNAN shu shaklga
    # qaytariladi (sana haqiqiyligi allaqachon tasdiqlangan).
    if model == "Purchase" and isinstance(toza.get("payment_due_date"), datetime):
        toza["payment_due_date"] = toza["payment_due_date"].strftime("%Y-%m-%d")
    # kech115 (G4-03): kirim hujjatining sanalari ham — `schemas.InventoryReceiptCreate` da MATN (`kirim_sanalari`
    # ularni `%Y-%m-%d` bilan o'qiydi).
    if model == "Receipt":
        for _sk in ("receipt_date", "payment_due_date"):
            if isinstance(toza.get(_sk), datetime):
                toza[_sk] = toza[_sk].strftime("%Y-%m-%d")
    # kech93 (8-band): parol qoidalari — yaratishda VA almashtirishda BIR XIL
    # (eng kami 6 belgi — avval faqat almashtirishda edi; eng ko'pi 72 bayt —
    # sababi `_PAROL_MAX_BAYT` izohida).
    if model in ("UserCreate", "UserPassword"):
        _pk = "password" if model == "UserCreate" else "new_password"
        _parol = toza.get(_pk)
        if _parol is None or len(_parol) < _PAROL_MIN:
            raise ValueError(f"Parol kamida {_PAROL_MIN} belgi")
        if len(_parol.encode("utf-8")) > _PAROL_MAX_BAYT:
            raise ValueError(f"Parol juda uzun: ko'pi bilan {_PAROL_MAX_BAYT} bayt "
                             f"(lotin harflarida {_PAROL_MAX_BAYT} belgi, kirill harflarida "
                             f"{_PAROL_MAX_BAYT // 2} belgi)")
    # Login bazaga chetidagi bo'shliqlarsiz yoziladi (`auth.create_user` va
    # login formasi ham `strip()` qiladi) — chegara ham shu qiymatga.
    if model == "UserCreate":
        toza["username"] = toza["username"].strip()
    if model == "ProductType":
        _koef = toza.get("coating_price_multiplier")
        # Numeric(5,2): 0.005 dan kichik koeffitsiyent bazada 0.00 bo'ladi.
        if _koef is not None and round(_koef, 2) < _PUL_ENG_KAM:
            raise ValueError(f"'coating_price_multiplier' kamida {_PUL_ENG_KAM} bo'lishi kerak "
                             "(bazada 2 xonagacha saqlanadi — kichigi 0 ga aylanadi)")
        # Sxemadagi `_qoplama_tekshir` bilan bir xil qoida — bu yerda o'qiladigan
        # matn bilan (sxema 422 ro'yxati UI da "[object Object]" bo'lib chiqardi).
        if toza.get("supports_coating") and _koef is None:
            raise ValueError("Qoplama yoqilgan — qoplama narx koeffitsiyentini kiriting "
                             "(masalan 2 yoki 2.5)")
    # Retsept nomi: bo'sh / faqat bo'shliq — "Standart" (bo'sh matn ilgari ham
    # shunday edi; faqat bo'shliqli nom esa '' bo'lib saqlanardi — O'LCHANGAN).
    if model == "BOM":
        toza["variant_name"] = (toza.get("variant_name") or "").strip() or "Standart"
    return toza


def _val_dump(data, model: str) -> dict:
    """crud ildizi uchun: tana → faqat BERILGAN maydonlar lug'ati.
    pydantic obyekt — `model_dump(exclude_unset=True)`; boshqa obyekt
    (ichki chaqiruv / test) — `model` qoidalaridagi atributlari; ichki
    ro'yxat qatorlari ham lug'atga aylantiriladi."""
    if isinstance(data, dict):
        return data
    if hasattr(data, "model_dump"):
        return data.model_dump(exclude_unset=True)
    qoidalar = _val_rules()[model]
    out = {}
    for k, q in qoidalar.items():
        if not hasattr(data, k):
            continue
        v = getattr(data, k)
        if q[0] == "royxat" and isinstance(v, list):
            v = [_val_dump(el, q[1]) for el in v]
        out[k] = v
    return out


def _penoplastmi(item) -> bool:
    """Material penoplastmi — `services.get_default_penoplast` bilan BIR XIL
    ta'rif: `is_penoplast` belgisi YOKI nomida \"penoplast\" (belgisi
    qo'yilmagan eski yozuvlar uchun tizimning o'zi shunday hisoblaydi)."""
    if getattr(item, "is_penoplast", False):
        return True
    return "penoplast" in (getattr(item, "item_name", "") or "").lower()


def _fp_tayyormi(fp) -> bool:
    """Mahsulot OMBORDAN CHIQADIGAN amal (sotish, savatcha, zaxiradan
    kamaytirish) uchun tayyormi. Jarayondagi (IN_PROGRESS) — yo'q: UI ham
    bu tugmalarni faqat tayyoriga beradi (`finished.html` — jarayondagida
    faqat \"✓ Sotuv\"). Ishlab chiqarish amallari (qo'shish, ishlab chiqarish
    braki) jarayondagiga ham RUXSAT — ular ishlab chiqarishning o'zi."""
    from models import ProductionStatus
    # UI bilan AYNAN bir xil: `inProgress = source === 'produced' &&
    # production_status === 'in_progress'`. Qaytarilgan (RETURNED) mahsulot
    # holati belgilanmay yaratiladi (bazada standart IN_PROGRESS) — u doim
    # sotiladi.
    return not (fp.source == StockSource.PRODUCED
                and fp.production_status == ProductionStatus.IN_PROGRESS)


def _fp_bosh_qoldiq(fp) -> float:
    """kech142 (zip 170, A-O01): sotsa / boshqa ishga olsa bo'ladigan qoldiq = qoldiq − band (manfiy emas). Band — MRP
    buyurtma detaliga ajratilgan qism (`models.FinishedProduct.reserved_quantity` — qoldiqning ICHIDA), uni faqat o'sha
    detalning yuk xati oladi. Bitta sotuv va savatcha sotuvi — shu bitta qoida."""
    return max(0.0, float(fp.quantity or 0) - max(0.0, float(fp.reserved_quantity or 0)))


def _fp_band_xabari(fp, soralgan: float) -> str:
    """kech142 (zip 170, A-O01): band sababli sotuv rad xabari — bitta va savatcha sotuvi uchun BIR matn (manfiy son
    yo'q: band qoldiqdan katta eski yozuvda ham «faqat 0»)."""
    band = max(0.0, float(fp.reserved_quantity or 0))
    return (f"{fp.name}: omborda {_miqdor_matn(float(fp.quantity or 0))} {fp.unit}, shundan {_miqdor_matn(band)} {fp.unit} "
            f"buyurtmaga band — sotsa bo'ladi faqat {_miqdor_matn(_fp_bosh_qoldiq(fp))} {fp.unit}, {_miqdor_matn(float(soralgan))} "
            f"sota olmaysiz. Band mahsulotni "
            f"sotish uchun avval «Bandni bekor qilish»")


def _fp_band_qoldiqqa_moslash(db: Session, fp, performed_by: str = None) -> float:
    """kech142 (zip 170, A-O08): tayyor mahsulotda band QOLDIQDAN oshmaydi — brak / yo'qotish avval bo'sh qismdan, keyin
    banddan (qoldiq bitta qatorda; buyurtma himoyalanadi). Kamaygan band miqdori qaytariladi (0 — o'zgarmadi); shu
    miqdor buyurtma detali uchun yana ishlab chiqarilishi kerak (`production_service.mrp_detal_kerak` uni o'zi ko'radi).
    `reserved_for_order_item_id` TOZALANMAYDI (tarixiy bog'lam). Ilgari band qoldiqdan katta qolardi (qoldiq 0, band 10):
    yuk xati, «Tayyor» va yangi ishlab chiqarish uchalasi rad etilib, buyurtma qotib qolardi."""
    band = float(fp.reserved_quantity or 0)
    q = max(0.0, float(fp.quantity or 0))
    if not _fp_tayyormi(fp) or band <= q + 1e-9:
        return 0.0
    fp.reserved_quantity = q
    log_activity(db, "updated", "finished_product", fp.id, fp.name, performed_by,
                 old_value=f"band: {_miqdor_jurnal(band)}",   # kech152 (zip 193)
                 new_value=(f"band: {_miqdor_jurnal(q)} — brak / yo'qotish; buyurtma detali #{fp.reserved_for_order_item_id} uchun "
                            f"yana {_miqdor_jurnal(band - q)} {fp.unit or ''} ishlab chiqarish kerak").replace("  ", " "),
                 company_id=getattr(fp, 'company_id', None), commit=False)
    return band - q


_FP_JARAYONDA_XABAR = "Mahsulot hali ishlab chiqarilmoqda — avval \"Tayyor\" deb belgilang"

# kech114 (K114-1, O'LCHANGAN — `work/k114/probe_mrp_tm.py`, asl `592a2e3`, SQLite = PG): «Tayyor mahsulotlar»
# sahifasida JARAYONDAGI MRP mahsuloti qatorida «✓ Sotuvga tayyor» (`complete_production`) va «✕ Bekor qilish»
# (`DELETE /api/finished/{id}`) bor edi — ikkalasi ham «Ishlab chiqarish» bo'limini CHETLAB o'tardi. MRP da xomashyo
# ishlab chiqarish «Yakunlash»ida yechiladi va tannarx o'shanda yoziladi: «Sotuvga tayyor» TM ni tannarx 0 bilan
# sotuvga chiqarardi (10 qop, 5 tasi 40 000 dan sotildi — foyda 200 000, aslida 168 500; keyin «Yakunlash» 63 000
# tannarxni qolgan 5 qopga yozardi — 1 qop tannarxi 2 barobar), «Bekor qilish» TM ni o'chirardi, ishlab chiqarish
# «jarayonda» qolardi va keyingi «Yakunlash» 63 000 so'mlik xomashyoni yechib, omborga HECH NARSA kiritmasdi.
# Endi MRP mahsuloti (`category == "dynamic_bom"` — faqat `production_service.start_production_order` yaratadi)
# holati faqat «Ishlab chiqarish» bo'limida o'zgaradi; jarayonda sotish / kamaytirish xabari ham o'sha yerga yo'llaydi.
_MRP_JARAYON_XABAR = ("Bu mahsulot «Ishlab chiqarish» bo'limida ishlab chiqarilmoqda — uni o'sha yerda «Yakunlash» "
                      "(xomashyo shunda yechiladi, tannarx yoziladi) yoki «Bekor qilish» kerak")


def _mrp_tm_mi(fp) -> bool:
    """MRP (Ishlab chiqarish bo'limi) yaratgan tayyor mahsulotmi — kech114 (K114-1)."""
    return (getattr(fp, "category", None) or "") == "dynamic_bom"


def _jarayonda_xabari(fp) -> str:
    """Jarayondagi mahsulotdan ombordan chiqadigan amal rad etilganda — qayerda tugatilishini aytadi (kech114)."""
    return _MRP_JARAYON_XABAR if _mrp_tm_mi(fp) else _FP_JARAYONDA_XABAR


def _clean_order_item_update(item_data) -> dict:
    """Detal tahriri tanasini tekshiradi va tozalangan nusxasini qaytaradi.

    Noma'lum yoki ruxsat etilmagan kalit, noto'g'ri tur yoki chegara
    tashqarisidagi qiymat — `ValueError` (marshrut uni 400 ga aylantiradi).
    Hech narsa yozilmasdan OLDIN chaqiriladi."""
    _son = _json_son
    if not isinstance(item_data, dict):
        raise ValueError("Noto'g'ri so'rov")
    notogri = sorted(str(k)[:40] for k in item_data
                     if k not in _ORDER_ITEM_UPDATE_FIELDS)
    if notogri:
        raise ValueError("Bu maydonni o'zgartirib bo'lmaydi: " + ", ".join(notogri[:10]))

    toza = {}
    for key, value in item_data.items():
        if key == "name":
            if not isinstance(value, str) or len(value.strip()) < 2:
                raise ValueError("Detal nomi kamida 2 belgi bo'lishi kerak")
            toza[key] = _schemas222.detal_nomi_tartib(value.strip())     # kech159 (zip 222): nom tartibi (saqlashda)
        elif key == "category":
            if value is not None and not isinstance(value, str):
                raise ValueError("'category' matn bo'lishi kerak")
            toza[key] = value
        elif key == "notes":
            if value is not None and not isinstance(value, str):
                raise ValueError("'notes' matn bo'lishi kerak")
            toza[key] = value
        elif key == "is_coated":
            if not isinstance(value, bool):
                raise ValueError("'is_coated' true yoki false bo'lishi kerak")
            toza[key] = value
        elif key == "penoplast_id":
            if value is None:
                toza[key] = None
            elif isinstance(value, bool) or not isinstance(value, int) or value <= 0:
                raise ValueError("'penoplast_id' musbat butun son bo'lishi kerak")
            else:
                toza[key] = value
        elif key in ("width", "thickness", "length"):
            toza[key] = _son(key, value, bosh_mumkin=True, musbat=False)
        elif key == "quantity":
            toza[key] = _son(key, value, bosh_mumkin=False, musbat=True)
        elif key == "unit_price":
            toza[key] = _son(key, value, bosh_mumkin=False, musbat=False,
                             chegara=_ORDER_ITEM_MAX_MONEY)
        elif key in ("unit_price_for_volume", "price_per_m3"):
            toza[key] = _son(key, value, bosh_mumkin=True, musbat=False,
                             chegara=_ORDER_ITEM_MAX_MONEY)
    return toza


def update_order_item(db: Session, item_id: int, item_data: dict,
                      company_id: int = None) -> Optional[OrderItem]:
    """Buyurtma detalini yangilash — ombor farq bo'yicha to'g'rilanadi.

    2026-09-21 (13-sizish): faqat `_ORDER_ITEM_UPDATE_FIELDS` dagi maydonlar
    o'zgaradi; boshqa kalit yoki noto'g'ri qiymat — `ValueError`.
    `penoplast_id` HAR DOIM detalning O'Z korxonasiga QAT'IY tekshiriladi
    (`company_id` berilmasa ham) — begona material 404."""
    import services

    _q = db.query(OrderItem).filter(OrderItem.id == item_id)
    if company_id is not None:
        _q = _q.filter(OrderItem.company_id == company_id)
    db_item = _q.first()
    if not db_item:
        return None
    # kech41 (5-bo'lim 14-band, K41-1) — QULF (101, buyurtma), yetkazish /
    # to'lov / qaytarish bilan BIR fazo. HAQIQIY PostgreSQL da O'LCHANGAN
    # (asl kod, `work/probe41.py`, 3 / 3 urinish): qulfsiz "topshirilgan"
    # tekshiruvi bir vaqtdagi yetkazishni ko'rmasdi —
    # detal 10 → 6 ga kamaytirilayotganda 8 topshirilsa, ikkalasi saqlanib
    # detal 6, topshirilgan 8 bo'lib qolardi (ikkala tartibda ham).
    # Naqsh `create_delivery` / `delete_delivery` dagi bilan bir xil:
    # yozilmagan o'zgarish yo'qolmasin (`flush`), qulf, so'ng qulf ostida
    # bazadan QAYTA o'qiladi (`expire_all`).
    if db_item.order_id is not None:
        db.flush()
        _pul_qulfi(db, 101, db_item.order_id)
        db.expire_all()
        db_item = _q.first()
        if not db_item:
            return None
        # kech145 (zip 182, mustaqil tekshiruv 2-bosqich P2-4): tayyor mahsulot guruhi XOMASHYODAN OLDIN qulflanadi — buyurtma yaratish
        # va «Yana ishlab chiqarish» avval guruhni, so'ng xomashyoni qulflaydi; teskari tartib (xomashyo → guruh) guruhdosh partiyalarda
        # bir-birini kutib qolardi (PG 40P01). Qayta qulflash bo'sh amal.
        _fp_qulf_guruh(db, [db_item.finished_product_id, (item_data or {}).get('finished_product_id')], db_item.company_id)

    order = db_item.order
    # MUHIM (2026-09 audit): o'chirilgan buyurtmaning detalini tahrirlab
    # bo'lmaydi — aks holda order_qty_normalized/delivery_percent o'chirish
    # va tiklash orasida o'zgarib, ombor hisobi (Loy/tayyor mahsulot
    # qaytarish-qayta yechish simmetriyasi) buzilib qolishi mumkin.
    if order and order.is_deleted:
        return None
    # kech141 (zip 169, audit A-P05 — O'LCHANGAN): «Tayyor» buyurtma detali narxi / miqdori shu yo'l bilan o'zgarardi (UI
    # chaqirmaydi, API ochiq) — yopilgan oy daromadi va kelishilgan summa hodisasiz qayta yozilardi. To'liq tahrir kabi rad;
    # narx o'zgarishi — «Kelishilgan summa» (✏️) orqali (o'z oyida).
    if order and order.status == OrderStatus.READY:
        raise ValueError("Tayyor buyurtma detalini o'zgartirib bo'lmaydi — narxni «Kelishilgan summa» (✏️) orqali tuzating")
    is_draft = order.status == OrderStatus.DRAFT if order else False
    # 117-band (kech95): tahrirdan / o'chirishdan OLDINGI jami (`_detal_ozgargach_buyurtma`; K110-1 — eski kelishilgan
    # summa u yerda o'qiladi).
    _eski_jami117 = float(order.total_amount or 0) if order else 0.0

    # 13-sizish: tana HECH NARSA yozilmasdan OLDIN tekshiriladi.
    item_data = _clean_order_item_update(item_data)
    # K95-1 (kech95): yangi detal jami va buyurtma jami sig'imi — HECH NARSA yozilmasdan OLDIN.
    _buyurtma_sigim_tekshir([{"quantity": item_data.get("quantity", db_item.quantity),
                              "unit_price": item_data.get("unit_price", db_item.unit_price)}])
    if order is not None:
        _jamilar_sigimi([_buyurtma_narx_jami(item_data.get("quantity", db_item.quantity) or 1,
                                             item_data.get("unit_price", db_item.unit_price) or 0)[1]]
                        + [it.total_price or 0 for it in order.items if it.id != db_item.id])
    if item_data.get("penoplast_id"):
        _require_inventory_of_company(db, [item_data["penoplast_id"]],
                                      db_item.company_id)

    # Topshirilgandan kam qilib bo'lmaydi.
    # 2026-09-21: ilgari `None` qaytarardi → marshrut "Detal topilmadi"
    # (404) derdi — foydalanuvchi uchun noto'g'ri sabab. Endi aniq xabar.
    # kech60 (57-band): omborga ortiqcha qo'yilgan qism ham chiqqan — undan kam qilib bo'lmaydi
    # (aks holda kamaytirish uning xomashyosini IKKINCHI marta qaytarardi).
    delivered = db_item.delivered_qty
    _ortiqcha_u = db_item.ortiqcha_qty
    if delivered + _ortiqcha_u > 0.001:
        cat = (item_data.get('category') or db_item.category or '').lower()
        new_qty = float(item_data.get('length') or db_item.length or 0) if cat == 'profil' \
                  else float(item_data.get('quantity') or db_item.quantity or 0)
        if new_qty < delivered + _ortiqcha_u - 0.001:
            if _ortiqcha_u > 0.001:
                raise ValueError(
                    f"Topshirilgan ({round(delivered, 3)}) va omborga ortiqcha qaytarilgan "
                    f"({round(_ortiqcha_u, 3)}) miqdordan kam qilib bo'lmaydi "
                    f"(kamida {round(delivered + _ortiqcha_u, 3)})")
            raise ValueError(
                f"Topshirilgan miqdordan ({round(delivered, 3)}) kam qilib bo'lmaydi")

    # Eski holat snapshot
    # MUHIM (2026-09 audit): "finished_product_id" va "sub_details" ham
    # SHART qo'shilishi kerak — bo'lmasa, _FakeItem/_item_volume_m3 buni
    # oddiy xomashyo detali deb hisoblab, (a) "Tayyor mahsulotdan"
    # tanlangan detal uchun HECH QACHON ombordan chiqmagan hajmni omborga
    # xato qo'shib yuboradi, (b) ichki qo'shimcha detal borligini
    # butunlay unutib, uning hajmini diffdan tashlab ketadi.
    old_sub_details = [{
        "category": s.category, "width": s.width, "thickness": s.thickness,
        "length": s.length, "quantity": s.quantity,
    } for s in (db_item.sub_details or [])]
    # 126-band (kech96, O'LCHANGAN `work/probe126.py` D1–D3): snapshotda qulflangan narx, detalning o'z
    # "1 m³ narxi" va buyurtma asosiy narxi YO'Q edi — Donalik (eski usul) hajmi penoplast tannarxidan
    # hisoblanib, 34 → 40 da 0.12 yechilardi (kerak 0.06). To'liq tahrir / yaratish bilan bir qoida.
    _bp126 = float(order.base_price) if order is not None and order.base_price is not None else None
    old_snap = [{
        "category": db_item.category,
        "width": db_item.width,
        "thickness": db_item.thickness,
        "length": db_item.length,
        "quantity": float(db_item.quantity or 1),
        "unit_price": float(db_item.unit_price or 0),
        "unit_price_for_volume": float(db_item.unit_price_for_volume) if db_item.unit_price_for_volume is not None else None,
        "penoplast_id": db_item.penoplast_id,
        "price_per_m3": float(db_item.price_per_m3) if db_item.price_per_m3 else None,
        "order_base_price": _bp126,
        "finished_product_id": db_item.finished_product_id,
        "sub_details": old_sub_details,
    }]

    for field, value in item_data.items():
        if hasattr(db_item, field):
            setattr(db_item, field, value)

    # 117-band (kech95): narx 2 xonaga (HALF_UP), jami SHU narxdan (`_buyurtma_narx_jami`).
    db_item.unit_price, db_item.total_price = _buyurtma_narx_jami(db_item.quantity or 1, db_item.unit_price or 0)
    # 126-band (kech96, O'LCHANGAN — yakuniy etalon `test_buyurtma_narx_jami` H, SQLite = PG): qulflangan narx va "1 m³ narxi"
    # ham bazaga yoziladigan qiymatga (2 xona, HALF_UP) — yaratish / to'liq tahrir bilan bir qoida (`_pul2_bosh`). Aks holda
    # yangi snapshot (endi bu kalitlarni o'qiydi) API dan kelgan 3 xonali qiymatni (3 997.125) ko'rardi, eski holat esa
    # bazadagi 3 997.13 ni — "1 m³ narxi" 10 da o'zgarishsiz tahrir 0.017 m³ qaytarardi; SQLite esa xom qiymatni saqlardi.
    db_item.unit_price_for_volume = _pul2_bosh(db_item.unit_price_for_volume)
    db_item.price_per_m3 = _pul2_bosh(db_item.price_per_m3)
    db.flush()

    # Yangi holat snapshot — "sub_details" bu funksiya orqali o'zgartirilmaydi
    # (item_data bunday maydonni yubormaydi), shuning uchun ESKISI bilan BIR
    # XIL qoladi (aks holda diff ularni "yo'qolgan" deb hisoblab, hajmini
    # noto'g'ri omborga qaytarib yuborardi).
    new_snap = [{
        "category": db_item.category,
        "width": db_item.width,
        "thickness": db_item.thickness,
        "length": db_item.length,
        "quantity": float(db_item.quantity or 1),
        "unit_price": float(db_item.unit_price or 0),
        "unit_price_for_volume": float(db_item.unit_price_for_volume) if db_item.unit_price_for_volume is not None else None,
        "penoplast_id": db_item.penoplast_id,
        "price_per_m3": float(db_item.price_per_m3) if db_item.price_per_m3 else None,
        "order_base_price": _bp126,
        "finished_product_id": db_item.finished_product_id,
        "sub_details": old_sub_details,
    }]

    # Omborni farq bo'yicha to'g'rilaymiz
    if not is_draft:
        services.adjust_inventory_diff(db, old_snap, new_snap, order_id=db_item.order_id,
                                       company_id=db_item.company_id, commit=False)
        # kech103 (K103-1, O'LCHANGAN `work/probe56tm.py` S10, SQLite = PG): TM li detal miqdori shu yo'l bilan
        # o'zgartirilsa tayyor mahsulot ombori TEGILMASDI (10 → 15 m: TM 5 m yechilmadi, buyurtma tannarxi esa
        # 15 m; 15 → 8: 7 m qaytmadi). To'liq tahrir (`update_order_full`) bilan BITTA yo'l — `_adjust_finished_diff`.
        if old_snap[0].get("finished_product_id") or db_item.finished_product_id:
            def _snap_miqdor(_s):
                if ((_s.get("category") or '').lower()) == 'profil':
                    return float(_s.get("length") or 0)
                return float(_s.get("quantity") or 0)
            _adjust_finished_diff(db, old_snap, new_snap, company_id=db_item.company_id,
                                  buyurtma_raqami=getattr(getattr(db_item, 'order', None), 'order_number', None), detallar=[{
                "detal": db_item, "eski_tm": old_snap[0].get("finished_product_id"),
                "eski_miqdor": _snap_miqdor(old_snap[0]), "eski_birlik": _tm_detal_birligi(db_item),
                "yangi_tm": db_item.finished_product_id, "yangi_miqdor": _snap_miqdor(new_snap[0])}])

    # Order summasi va kelishilgan summa (117-band — `_detal_ozgargach_buyurtma`)
    if order:
        _detal_ozgargach_buyurtma(db, order, _eski_jami117)

    db.commit()
    db.refresh(db_item)
    return db_item


def record_cash_transaction(db: Session, category: str, amount: float, notes: str = None,
                           performed_by: str = None, company_id: int = None, hisob=None):
    """Kassaga qo'lda ta'sir qiladigan yozuv qo'shadi (boshlang'ich balans,
    Usta KPI to'landi, Ehson to'landi). amount — musbat (kirim) yoki
    manfiy (chiqim) bo'lishi mumkin."""
    from models import CashTransaction
    # M6 (2026-09-18) — TENANT: `CashTransaction`da ota-FK yo'q, shuning
    # uchun `_tenant_guard` uni to'ldira olmaydi — company_id ANIQ
    # berilmasa yozuv bazadagi vaqtinchalik DEFAULT 1 ga tushib qolardi.
    # kech155 (zip 210): qaysi pul hisobidan (Usta KPI / Ehson); boshlang'ich balans — hisobsiz (harakat emas)
    _hid210 = None if category == "boshlangich" else pul_hisobi_id(db, company_id, hisob=hisob)
    # kech155 (zip 210, sinov saytida JONLI TOPILDI 23.10 20:22): BITTA bosishdan («− Usta KPI to'landi»; brauzer BITTA so'rov yuborgan —
    # `performance` yozuvi, 4,8 s) IKKITA yozuv 4 s farq bilan — javob kechikkanda so'rov serverga ikkinchi marta yetgan (yangilanish
    # paytida proksi). Takror: `PUL_TAKROR_SONIYA` ichida AYNAN shu tur, summa, hisob va izoh — yangi yozuv YO'Q, mavjudi qaytadi
    # (`_is_duplicate_submit`; o'tkazish va qoldiqdagi qoida). Qulf (212) ostida — ikkinchi so'rov birinchisi saqlangach o'qiydi.
    from datetime import timedelta as _td210k
    _pul_qulfi(db, 212, company_id)
    _q210 = db.query(CashTransaction).filter(CashTransaction.company_id == company_id, CashTransaction.category == category,
                                             CashTransaction.amount == amount,
                                             CashTransaction.created_at >= datetime.utcnow() - _td210k(seconds=PUL_TAKROR_SONIYA))
    _q210 = _q210.filter(CashTransaction.hisob_id.is_(None) if _hid210 is None else CashTransaction.hisob_id == _hid210)
    _q210 = _q210.filter(CashTransaction.notes.is_(None) if notes is None else CashTransaction.notes == notes)
    _old210 = _q210.order_by(CashTransaction.id.desc()).first()
    if _old210 is not None:
        db.commit()          # qulf bo'shaydi (hech narsa yozilmagan)
        _old210._is_duplicate_submit = True
        return _old210
    tx = CashTransaction(company_id=company_id, category=category, amount=amount,
                         notes=notes, performed_by=performed_by, hisob_id=_hid210)
    db.add(tx)
    db.commit()
    return tx


def get_cash_transactions(db: Session, limit: int = 100, company_id: int = None) -> List:
    """Kassaga qo'lda qilingan yozuvlar tarixi (M6 — tenant-safe)."""
    from models import CashTransaction
    q = db.query(CashTransaction)
    if company_id is not None:
        q = q.filter(CashTransaction.company_id == company_id)
    return q.order_by(CashTransaction.created_at.desc()).limit(limit).all()


def delete_cash_transaction(db: Session, tx_id: int, company_id: int = None) -> bool:
    """Kassaga qo'lda qo'shilgan yozuvni o'chiradi (faqat Admin).

    2026-09-18 — bu funksiya M6 sinovidan qolgan yozuvlarni tozalash uchun
    qo'shildi: ilgari `CashTransaction` uchun o'chirish yo'li UMUMAN yo'q
    edi (faqat `factory_reset_all_data()` butun bazani tozalash orqali),
    shuning uchun noto'g'ri kiritilgan kassa yozuvini tuzatib bo'lmasdi.

    TENANT: yozuv FAQAT shu korxonadan topiladi (aks holda False → 404).
    Kassa balansi alohida saqlanmaydi — u har safar joriy yozuvlardan
    qayta hisoblanadi, shuning uchun bu yerda boshqa hech narsani
    yangilash shart emas."""
    from models import CashTransaction
    q = db.query(CashTransaction).filter(CashTransaction.id == tx_id)
    if company_id is not None:
        q = q.filter(CashTransaction.company_id == company_id)
    tx = q.first()
    if not tx:
        return False
    _keshbek_boglami_tekshir(db, cash_tx_id=tx.id)              # kech186 (zip 253)
    db.delete(tx)
    db.commit()
    return True


# ══════════════════════════════════════════════════════════════════════════════════════════════════════════════
# kech155 (zip 210 «Naqd / Bank / Karta» — egasi so'rovi 23.10 15:56, ko'rinish tasdig'i 16:1x, `work/k210/ekran/`): PUL HISOBLARI.
# Kirim (mijoz to'lovi, tayyor sotuv) — to'lov USULIDAN (naqd → «Naqd pul», plastik / karta → «Karta», o'tkazma / bank → «Bank»);
# chiqim — formadagi «Qaysi hisobdan» (`hisob` — turi yoki id), berilmasa «Naqd pul». Qoldiq — `services.pul_hisob_balanslari`.
# ══════════════════════════════════════════════════════════════════════════════════════════════════════════════
_USUL_HISOB_TURI = {"naqd": "naqd", "cash": "naqd", "plastik": "karta", "karta": "karta", "card": "karta",
                    "o'tkazma": "bank", "bank": "bank", "transfer": "bank"}
PUL_HISOB_CHEGARA = 999_999_999_999.99          # bitta summa / qoldiq yuqori chegarasi (Numeric(14, 2))


def pul_hisoblari(db: Session, company_id: int, faqat_faol: bool = True) -> list:
    '''Korxona pul hisoblari (`tartib`, `id`). Bitta ham yo'q bo'lsa — standart uchtasi («Naqd pul», «Bank», «Karta») yaratiladi
    (faqat `flush`; `commit` — chaqiruvchida). PostgreSQL da parallel yaratish `uq_pul_hisoblari_company_nomi` bilan to'siladi —
    savepoint ichida urinib, band bo'lsa mavjudlari olinadi (`standart_yonalish` naqshi).'''
    from models import PulHisobi, PUL_HISOB_STANDART
    from sqlalchemy.exc import IntegrityError as _IE210
    if company_id is None:
        return []
    rows = (db.query(PulHisobi).filter(PulHisobi.company_id == company_id)
            .order_by(PulHisobi.tartib, PulHisobi.id).all())
    if not rows:
        yangi = [PulHisobi(company_id=company_id, nomi=_n, turi=_t, tartib=_k, faol=True) for _n, _t, _k in PUL_HISOB_STANDART]
        if db.bind.dialect.name == "postgresql":
            try:
                with db.begin_nested():
                    db.add_all(yangi)
                    db.flush()
            except _IE210:
                pass
        else:
            db.add_all(yangi)
            db.flush()
        rows = (db.query(PulHisobi).filter(PulHisobi.company_id == company_id)
                .order_by(PulHisobi.tartib, PulHisobi.id).all())
    return [h for h in rows if h.faol is not False] if faqat_faol else rows


def pul_hisobi_aniqla(db: Session, company_id: int, hisob=None, hisob_id=None, usul=None, standart: str = "naqd"):
    '''Pul yozuvi qaysi hisobga: `hisob` (turi — naqd / bank / karta, yoki raqam — id) yoki `hisob_id` (SHU korxonaning faol hisobi) →
    `usul` (to'lov usuli: naqd / plastik / o'tkazma / karta / bank) → `standart` turi; turdan — shu turdagi birinchi faol hisob.
    Noto'g'ri / begona / nofaol hisob — `ValueError` (o'zbekcha, hech narsa yozilmaydi). Korxona noma'lum (`company_id` None) — None
    (yozuv NULL qoladi; qoldiq hisobida usuldan / «Naqd pul» ga).'''
    if company_id is None:
        return None
    royxat = pul_hisoblari(db, company_id)
    if hisob is not None and not isinstance(hisob, bool) and str(hisob).strip() != "":
        _h = str(hisob).strip().lower()
        if _h.isdigit():
            if hisob_id is None:
                hisob_id = int(_h)
        elif _h in _USUL_HISOB_TURI:
            _tur = _USUL_HISOB_TURI[_h]
            for h in royxat:
                if h.turi == _tur:
                    return h
            raise ValueError(f"«{hisob}» turidagi faol pul hisobi yo'q")
        else:
            raise ValueError(f"Pul hisobi noto'g'ri: «{hisob}» (naqd, bank yoki karta bo'lishi kerak)")
    elif isinstance(hisob, bool):
        raise ValueError("Pul hisobi noto'g'ri")
    if hisob_id is not None:
        if isinstance(hisob_id, bool):
            raise ValueError("Pul hisobi noto'g'ri")
        try:
            _id = int(hisob_id)
        except (TypeError, ValueError):
            raise ValueError("Pul hisobi noto'g'ri")
        for h in royxat:
            if h.id == _id:
                return h
        raise ValueError("Pul hisobi topilmadi (yoki faol emas)")
    _uv = getattr(usul, "value", usul)
    _tur = _USUL_HISOB_TURI.get(str(_uv).strip().lower()) if _uv is not None else None
    _tur = _tur or standart
    for h in royxat:
        if h.turi == _tur:
            return h
    return royxat[0] if royxat else None


def pul_hisobi_id(db: Session, company_id: int, **kw):
    '''`pul_hisobi_aniqla` — faqat id (korxona noma'lum — None).'''
    h = pul_hisobi_aniqla(db, company_id, **kw)
    return h.id if h is not None else None


def _pul_summa210(qiymat, nom: str, nol_mumkin: bool) -> float:
    '''Qoldiq / o'tkazish summasi — chekli son, tiyingacha, [0 yoki 0,01 … PUL_HISOB_CHEGARA]; aks holda `ValueError`.'''
    import math as _m210
    if isinstance(qiymat, bool) or qiymat is None:
        raise ValueError(f"{nom}: summa kiritilmagan")
    try:
        x = float(qiymat)
    except (TypeError, ValueError):
        raise ValueError(f"{nom}: summa son bo'lishi kerak")
    if not _m210.isfinite(x):
        raise ValueError(f"{nom}: summa noto'g'ri")
    if abs(round(x, 2) - x) > 1e-9:
        raise ValueError(f"{nom}: summa tiyingacha (ko'pi bilan 2 xona) bo'lishi kerak")
    if x < 0:
        raise ValueError(f"{nom}: summa manfiy bo'lmasin")
    if x == 0 and not nol_mumkin:
        raise ValueError(f"{nom}: summa musbat bo'lishi kerak")
    if x > PUL_HISOB_CHEGARA:
        raise ValueError(f"{nom}: summa juda katta")
    return round(x, 2)


def pul_qoldiq_kirit(db: Session, company_id: int, qoldiqlar, izoh: str = None, performed_by: str = None) -> list:
    '''Hisob(lar)ning HAQIQIY qoldig'i — HOZIRGI holat («hozir qancha bor»); `qoldiqlar` — [(hisob_id, summa), …]. Birinchi marta —
    qoldig'i hali yo'q HAMMA faol hisob birga (aks holda ValueError: bitta hisobning qoldig'i bilan «Kassa + bank» yarim bo'lardi).
    Qayta (sanash) — istalgan hisob(lar). `dastur_summa` — shu payt dastur hisoblagan qoldiq (farq jurnalga). Har hisobga jurnal yozuvi —
    amal bilan BITTA tranzaksiyada. Takror (`PUL_TAKROR_SONIYA` ichida o'sha hisoblar va summalar) — mavjud yozuvlar. `commit` — shu yerda.'''
    from models import PulHisobiQoldiq
    import services as _sv210
    if company_id is None:
        raise ValueError("Korxona aniqlanmadi")
    if not isinstance(qoldiqlar, (list, tuple)) or not qoldiqlar:
        raise ValueError("Kamida bitta hisob qoldig'i kiritilsin")
    if izoh is not None:
        izoh = str(izoh).strip()[:300] or None
    royxat = {h.id: h for h in pul_hisoblari(db, company_id)}
    _pul_qulfi(db, 211, company_id)
    _bor = {hid for (hid,) in db.query(PulHisobiQoldiq.hisob_id).filter(PulHisobiQoldiq.company_id == company_id).distinct().all()}
    kirdi = {}
    for el in qoldiqlar:
        try:
            _hid, _summa = el
        except (TypeError, ValueError):
            raise ValueError("Qoldiq qatori noto'g'ri")
        h = pul_hisobi_aniqla(db, company_id, hisob_id=_hid)
        if h.id in kirdi:
            raise ValueError(f"«{h.nomi}» ikki marta kiritildi")
        kirdi[h.id] = _pul_summa210(_summa, h.nomi, nol_mumkin=True)
    # takror yuborish (ikki oyna / ikki bosish / tarmoq qaytarishi — review210 №6, PG da O'LCHANGAN: ikki parallel birinchi so'rov 6 qator
    # va 3 ta «farq 0» jurnal yozuvi): `PUL_TAKROR_SONIYA` ichida AYNAN shu hisoblarga AYNAN shu summalar yozilgan bo'lsa — yangi qator
    # yo'q, o'shalar qaytadi (`_is_duplicate_submit`). Qulf (211) ostida — ikkinchi so'rov birinchisi saqlangach o'qiydi.
    from datetime import timedelta as _td210q
    _yaqin = {}
    for _q in (db.query(PulHisobiQoldiq).filter(PulHisobiQoldiq.company_id == company_id,
                                                PulHisobiQoldiq.vaqt >= datetime.utcnow() - _td210q(seconds=PUL_TAKROR_SONIYA))
               .order_by(PulHisobiQoldiq.vaqt.desc(), PulHisobiQoldiq.id.desc()).all()):
        _yaqin.setdefault(_q.hisob_id, _q)
    if all(hid in _yaqin and abs(float(_yaqin[hid].summa) - summa) < 0.005 for hid, summa in kirdi.items()):
        _takror = [_yaqin[hid] for hid in kirdi]
        db.commit()          # qulf bo'shaydi (hech narsa yozilmagan; birinchi so'rovda yaratilgan standart hisoblar saqlanadi)
        for _q in _takror:
            _q._is_duplicate_submit = True
        return _takror
    _yoq = [h for hid, h in royxat.items() if hid not in _bor and hid not in kirdi]
    if _yoq:
        raise ValueError("Birinchi marta hamma hisob qoldig'i birga kiritiladi: " + ", ".join(h.nomi for h in _yoq) + " — kiritilmadi")
    _hozir = _sv210.pul_hisob_balanslari(db, company_id)
    _dastur = {x["id"]: x["balans"] for x in _hozir["hisoblar"] if x.get("balans") is not None}
    _vaqt = datetime.utcnow()
    yangi = []
    for hid, summa in kirdi.items():
        q = PulHisobiQoldiq(company_id=company_id, hisob_id=hid, vaqt=_vaqt, summa=summa,
                            dastur_summa=(_dastur.get(hid) if hid in _bor else None), izoh=izoh, performed_by=performed_by)
        db.add(q)
        yangi.append(q)
    db.flush()
    for q in yangi:
        h = royxat[q.hisob_id]
        if q.dastur_summa is None:
            _m = f"boshlang'ich qoldiq: {audit_son(q.summa, 2)} so'm"
        else:
            _f = round(float(q.summa) - float(q.dastur_summa), 2)
            _m = (f"qoldiq sanaldi: {audit_son(q.summa, 2)} so'm · dasturda: {audit_son(q.dastur_summa, 2)} so'm · farq: "
                  f"{'+' if _f > 0 else ''}{audit_son(_f, 2)} so'm")
        log_activity(db, "created", "pul_hisobi", q.id,
                     entity_label=f"{h.nomi} — qoldiq ({_tashkent_vaqt(q.vaqt).strftime('%d.%m.%Y %H:%M')})",
                     performed_by=performed_by, new_value=_m + (f" · izoh: {izoh}" if izoh else ""),
                     company_id=company_id, commit=False)
    db.commit()
    return yangi


def pul_qoldiq_ochir(db: Session, company_id: int, qoldiq_id: int, performed_by: str = None) -> bool:
    '''Xato kiritilgan qoldiqni o'chiradi (shu korxonaniki bo'lmasa — False → 404). Hisob oldingi qoldig'iga qaytadi (yo'q bo'lsa —
    «Kassa + bank» avvalgi umumiy hisobga). Jurnal — amal bilan bitta tranzaksiyada.'''
    from models import PulHisobiQoldiq, PulHisobi
    q = (db.query(PulHisobiQoldiq).filter(PulHisobiQoldiq.id == qoldiq_id, PulHisobiQoldiq.company_id == company_id).first()
         if company_id is not None else None)
    if q is None:
        return False
    h = db.query(PulHisobi).filter(PulHisobi.id == q.hisob_id, PulHisobi.company_id == company_id).first()
    log_activity(db, "deleted", "pul_hisobi", q.id,
                 entity_label=f"{h.nomi if h else '?'} — qoldiq ({_tashkent_vaqt(q.vaqt).strftime('%d.%m.%Y %H:%M') if q.vaqt else '-'})",
                 performed_by=performed_by, old_value=f"{audit_son(q.summa, 2)} so'm", company_id=company_id, commit=False)
    db.delete(q)
    db.commit()
    return True


def pul_otkazma_yoz(db: Session, company_id: int, dan_hisob_id, ga_hisob_id, summa, izoh: str = None,
                    performed_by: str = None):
    '''Hisoblar orasida o'tkazish (bankdan naqd yechish va h.k.): ikkala hisob SHU korxonaning faol hisobi, har xil; summa > 0.
    Takror yuborish (o'sha juftlik va summa `PUL_TAKROR_SONIYA` ichida) — mavjud yozuv qaytadi (`_is_duplicate_submit`). Jurnal — bitta
    tranzaksiyada. `commit` — shu yerda.'''
    from datetime import timedelta as _td210
    from models import PulOtkazmasi
    if company_id is None:
        raise ValueError("Korxona aniqlanmadi")
    dan = pul_hisobi_aniqla(db, company_id, hisob_id=dan_hisob_id)
    ga = pul_hisobi_aniqla(db, company_id, hisob_id=ga_hisob_id)
    if dan.id == ga.id:
        raise ValueError("Qayerdan va qayerga — har xil hisob bo'lishi kerak")
    _s = _pul_summa210(summa, "O'tkazish", nol_mumkin=False)
    if izoh is not None:
        izoh = str(izoh).strip()[:300] or None
    _pul_qulfi(db, 210, company_id)
    _old = (db.query(PulOtkazmasi).filter(PulOtkazmasi.company_id == company_id, PulOtkazmasi.dan_hisob_id == dan.id,
                                          PulOtkazmasi.ga_hisob_id == ga.id, PulOtkazmasi.summa == _s,
                                          PulOtkazmasi.created_at >= datetime.utcnow() - _td210(seconds=PUL_TAKROR_SONIYA))
            .order_by(PulOtkazmasi.id.desc()).first())
    if _old is not None:
        _old._is_duplicate_submit = True
        return _old
    o = PulOtkazmasi(company_id=company_id, dan_hisob_id=dan.id, ga_hisob_id=ga.id, summa=_s, sana=datetime.utcnow(),
                     izoh=izoh, performed_by=performed_by)
    db.add(o)
    db.flush()
    log_activity(db, "created", "pul_otkazmasi", o.id, entity_label=f"O'tkazish: {dan.nomi} → {ga.nomi}",
                 performed_by=performed_by, new_value=f"{audit_son(_s, 2)} so'm" + (f" · izoh: {izoh}" if izoh else ""),
                 company_id=company_id, commit=False)
    db.commit()
    return o


def pul_otkazma_ochir(db: Session, company_id: int, otkazma_id: int, performed_by: str = None) -> bool:
    '''O'tkazishni o'chiradi (shu korxonaniki bo'lmasa — False → 404); jurnal — bitta tranzaksiyada.'''
    from models import PulOtkazmasi, PulHisobi
    o = (db.query(PulOtkazmasi).filter(PulOtkazmasi.id == otkazma_id, PulOtkazmasi.company_id == company_id).first()
         if company_id is not None else None)
    if o is None:
        return False
    _n = {h.id: h.nomi for h in db.query(PulHisobi).filter(PulHisobi.company_id == company_id).all()}
    log_activity(db, "deleted", "pul_otkazmasi", o.id,
                 entity_label=f"O'tkazish: {_n.get(o.dan_hisob_id, '?')} → {_n.get(o.ga_hisob_id, '?')}",
                 performed_by=performed_by, old_value=f"{audit_son(o.summa, 2)} so'm" + (f" · izoh: {o.izoh}" if o.izoh else ""),
                 company_id=company_id, commit=False)
    db.delete(o)
    db.commit()
    return True


def get_setting(db: Session, key: str, default: str = None,
                company_id: int = None) -> str:
    """Korxona sozlamasini o'qiydi (masalan Ehson foizi).

    2026-09-18 — M8/F1a: qidiruv FAQAT `key` bo'yicha edi, ya'ni ikki
    korxonali bazada bir korxona boshqasining sozlamasini o'qib olardi.
    Endi `(company_id, key)` juftligi bo'yicha."""
    from models import CompanySetting
    q = db.query(CompanySetting).filter(CompanySetting.key == key)
    if company_id is not None:
        q = q.filter(CompanySetting.company_id == company_id)
    row = q.first()
    return row.value if row else default


def set_setting(db: Session, key: str, value: str, company_id: int = None):
    """Korxona sozlamasini saqlaydi/yangilaydi.

    2026-09-18 — M8/F1a: qidiruv ham, yangi yozuv ham korxona bilan
    bog'lanadi. Ilgari faqat `key` bo'yicha qidirilardi — bu o'qish
    sizishi emas, MA'LUMOT BUZILISHI edi: B korxona Ehson foizini
    o'zgartirsa, A korxonaning qatori qayta yozilardi."""
    from models import CompanySetting
    q = db.query(CompanySetting).filter(CompanySetting.key == key)
    if company_id is not None:
        q = q.filter(CompanySetting.company_id == company_id)
    row = q.first()
    if row:
        row.value = value
    else:
        row = CompanySetting(company_id=company_id, key=key, value=value)
        db.add(row)
    db.commit()


def log_activity(db: Session, action: str, entity_type: str, entity_id: int,
                  entity_label: str = None, performed_by: str = None,
                  old_value: str = None, new_value: str = None,
                  company_id: int = None, commit: bool = True):
    """Muhim amallarni audit uchun yozib boradi (o'chirish/tiklash/yaratish/
    tahrirlash). old_value/new_value — ixtiyoriy, qisqa tavsif (masalan
    "Jami: 850 000 so'm, 3 ta detal") — har bir maydonni emas, faqat
    tezda "nima o'zgargani"ni ko'rsatish uchun.

    kech110 (2c): `commit=False` — yozuv chaqiruvchining tranzaksiyasiga qo'shiladi (amal bilan BIRGA saqlanadi yoki
    birga bekor bo'ladi — MRP amallari: retsept, ishlab chiqarish boshlash / yakunlash / bekor qilish)."""
    from models import ActivityLog
    # M7 (2026-09-18) — TENANT: `ActivityLog`da company_id ustuni bor, lekin
    # ota-FK yo'q va model `_TENANT_RULES` da emas — shuning uchun qiymat
    # ANIQ berilmasa yozuv bazadagi vaqtinchalik DEFAULT 1 ga tushardi.
    # Ya'ni B korxonaning audit izi A ning bazasiga yozilardi, B da esa
    # audit izi umuman bo'lmasdi (lokal ikki korxonali sinovda tasdiqlangan).
    entry = ActivityLog(
        company_id=company_id,
        action=action, entity_type=entity_type, entity_id=entity_id,
        entity_label=entity_label, performed_by=performed_by,
        old_value=old_value, new_value=new_value
    )
    db.add(entry)
    if commit:
        # kech144 (zip 172, N4 — O'LCHANGAN, production 12.10 11:47): ilgari amal o'zgarishlari va jurnal yozuvi BITTA
        # `commit` da edi. Jurnal yozuvi bazaga sig'masa (production da `new_value` VARCHAR(255) edi) yoki ulanish uzilsa,
        # 7 ta chaqiruvchi xatoni `except Exception: pass` bilan yutardi, `rollback` qilinmasdi — sessiya buzuq qolar,
        # keyingi o'qishda PendingRollbackError → 500 (buyurtma tahriri: o'zgarish SAQLANGAN, foydalanuvchi esa xato
        # ko'radi va qayta bosadi — buyurtma yaratishda TAKROR buyurtma xavfi). Endi: avval amalning O'Z o'zgarishlari
        # (xatosi — chaqiruvchiniki, avvalgidek), keyin jurnal yozuvi alohida; u yozilmasa — amal saqlangan qoladi,
        # sessiya toza, sabab «Xatoliklar» ga (`_jurnal_yozilmadi`). `crud.bitta_tranzaksiya` ichida (commit = flush) —
        # PostgreSQL da SAVEPOINT (amalning tranzaksiyasi buzilmaydi); SQLite da savepoint yo'q — avvalgidek butun
        # tranzaksiya bekor bo'ladi (hech narsa yarim saqlanmaydi).
        yagona = "commit" in db.__dict__          # bitta_tranzaksiya: `db.commit` = `db.flush`
        db.expunge(entry)
        db.commit()
        try:
            if yagona and db.get_bind().dialect.name == "postgresql":
                with db.begin_nested():
                    db.add(entry)
                return
            db.add(entry)
            db.commit()
        except Exception as e:                    # noqa: BLE001 — jurnal amalni buzmaydi; sabab «Xatoliklar» da
            if yagona and db.get_bind().dialect.name != "postgresql":
                raise
            if not yagona:
                db.rollback()
            _jurnal_yozilmadi(db, e, action, entity_type, entity_id, entity_label, performed_by, company_id)


def _jurnal_yozilmadi(db: Session, xato, action, entity_type, entity_id, entity_label, performed_by, company_id):
    """kech144 (zip 172, N4): «Faoliyat jurnali» yozuvi saqlanmadi — sabab «Xatoliklar» ga ALOHIDA sessiyada (asosiy sessiya
    tranzaksiyasiga tegmaydi). Bu yozuvning o'zi ham yiqilsa — faqat server logi (amal baribir saqlangan)."""
    import re as _re144
    # SQLAlchemy xato matnida so'rov qiymatlari bo'ladi («[parameters: …]») — server logiga ham yashirilgan holda (`log_error` naqshi)
    matn = _re144.sub(r"\[parameters:.*?\]", "[parameters: YASHIRINGAN]",
                      f"Faoliyat jurnaliga yozilmadi ({action} · {entity_type} #{entity_id}"
                      f"{' · ' + str(entity_label) if entity_label else ''}) — amalning o'zi saqlandi: {xato}", flags=_re144.DOTALL)
    print(f"⚠️ {matn[:500]}")
    try:
        from sqlalchemy.engine import Engine as _Engine144
        bog = db.get_bind()
        if not isinstance(bog, _Engine144):
            return
        from sqlalchemy.orm import Session as _Session144
        from sqlalchemy import text as _text144
        with _Session144(bind=bog) as _s:
            if bog.dialect.name == "postgresql":
                # asosiy tranzaksiya (bitta_tranzaksiya) hali ochiq — kutib qolmaslik uchun (qulf bo'lsa — tez voz kechadi)
                _s.execute(_text144("SET LOCAL lock_timeout = '3s'"))
            log_error(_s, matn, endpoint=f"log_activity:{action}", performed_by=performed_by, company_id=company_id)
    except Exception as e2:                       # noqa: BLE001
        print(f"⚠️ «Xatoliklar» ga ham yozilmadi: {e2}")


# kech115 (G6-01): «O'chirilganlar» sahifasi jurnalidagi amallar — faqat o'chirish / tiklash / butunlay o'chirish.
CHIQINDI_JURNAL_AMALLARI = ("deleted", "restored", "permanently_deleted")


def get_activity_log(db: Session, limit: int = 100, company_id: int = None, amallar=None) -> List:
    """So'nggi audit yozuvlari (M7 — tenant-safe).

    kech115 (G6-01, O'LCHANGAN — audit: «O'chirilganlar» jurnali filtrsiz 50 yozuv olib, «o'chirildi» / «tiklandi» dan
    boshqa HAMMA amalni — buyurtma yaratildi, ishlab chiqarish boshlandi / yakunlandi, tahrir — «butunlay o'chirildi»
    deb ko'rsatardi; o'chirilgan buyurtma 0 ta bo'lsa ham jurnal «ORD-001-5 butunlay o'chirildi» bilan to'la edi):
    `amallar` berilsa — faqat shu amal turlari (`CHIQINDI_JURNAL_AMALLARI`)."""
    from models import ActivityLog
    q = db.query(ActivityLog)
    if company_id is not None:
        q = q.filter(ActivityLog.company_id == company_id)
    if amallar:
        q = q.filter(ActivityLog.action.in_(list(amallar)))
    return q.order_by(ActivityLog.created_at.desc()).limit(limit).all()


def _company_of_username(db: Session, username: str):
    """Login vaqtida korxonani SERVER tomonda aniqlaydi (M7).

    `User.username` butun tizim bo'yicha YAGONA (`unique=True`), shuning
    uchun foydalanuvchi nomidan korxona bir qiymatli aniqlanadi — mijoz
    yuborgan hech qanday `company_id` ga ishonilmaydi. Nom topilmasa
    (mavjud bo'lmagan hisobga urinish) None qaytadi."""
    from models import User, Employee
    if not username:
        return None
    u = db.query(User).filter(User.username == username).first()
    if u is not None:
        return getattr(u, "company_id", None)
    # kech146 (zip 183, audit J1 — O'LCHANGAN SQLite = PG): hodim telefoni bo'yicha TAXMIN QILINMAYDI. Ilgari `Employee.phone == kalit`
    # (birinchisi, HAMMA korxonalar) — telefon «+998 …» ko'rinishida saqlangan bo'lsa topilmasdi (hodim kirishlari «Kirish tarixi» da
    # yo'q), boshqa korxonada shu raqamli hodim / login bo'lsa yozuv O'SHA korxonaga tushardi (begona hodimning telefoni, IP si). Hodim
    # yo'llari (`/hodim/login`, `/api/hodim/pin`) korxonani o'zlari aniq beradi.
    return None


def log_login_attempt(db: Session, username: str, success: bool, ip_address: str = None,
                      user_agent: str = None, company_id: int = None, aniqla: bool = True):
    """Tizimga kirish urinishini yozib boradi (muvaffaqiyatli yoki muvaffaqiyatsiz).

    M7 — TENANT: korxona foydalanuvchi NOMIDAN aniqlanadi (yuqoridagi
    `_company_of_username`). Nom noma'lum bo'lsa (mavjud bo'lmagan hisob)
    yozuv korxonasiz qoladi — u hech bir tenantning ro'yxatida
    ko'rinmaydi, faqat IP bo'yicha rate-limit uchun ishlatiladi."""
    from models import LoginHistory
    # kech146 (zip 183, J1): `aniqla=False` — korxona noma'lum (masalan hodim kirishida korxona kodi topilmadi) va TAXMIN QILINMAYDI.
    if company_id is None and aniqla:
        company_id = _company_of_username(db, username)
    entry = LoginHistory(company_id=company_id, username=username, success=success,
                         ip_address=ip_address, user_agent=user_agent)
    db.add(entry)
    db.commit()


def check_login_rate_limit(db: Session, username: str, ip_address: str = None,
                            max_attempts: int = 5, window_minutes: int = 15, ip_max_attempts: int = 60,
                            login_jami_max: int = 30, tanish_kun: int = 30, company_id: int = None,
                            aniqla: bool = True) -> dict:
    """Rate limit — oxirgi `window_minutes` daqiqadagi MUVAFFAQIYATSIZ urinishlar bo'yicha kirishni bloklaydi. Mavjud LoginHistory
    jadvalidan foydalanadi — yangi jadval kerak emas.

    kech116 (U-01): IP chegarasi 5 → 20. Sabab (O'LCHANGAN): bitta ofis / bitta uyali operator NAT i ortidagi hamma xodim bitta
    IP da — bitta xodimning 5 xatosi butun ofisni 15 daqiqa kiritmay qo'yardi.

    kech143 (zip 171, AUDIT A-X08 — O'LCHANGAN `work/audit/tasdiq/himoya/p_himoya.py` X08a / X09g, SQLite = PG): foydalanuvchi
    nomi bo'yicha 5 xato HAMMA joydan kirishni yopardi — begona odam o'z kompyuteridan 5 marta noto'g'ri parol terib istalgan
    hisobni (platforma egasini ham; hodim telefonini ham) 15 daqiqaga ishdan chiqarardi: egasi boshqa joydan TO'G'RI parol
    bilan ham kira olmasdi. Endi:
      * (login, IP) juftligi — 5 xato: shu IP dan shu hisobga (parol terish shu yerda to'xtaydi; asl qoida shu IP uchun);
      * IP — 20 xato: shu IP dan istalgan hisoblarga (o'zgarmagan);
      * login bo'yicha JAMI — `login_jami_max` (30) xato turli IP lardan (tarqoq parol terish): bloklanadi, LEKIN shu login shu
        IP dan oxirgi `tanish_kun` (30) kunda MUVAFFAQIYATLI kirgan bo'lsa — yo'q (egasi o'z ofisi / uyidan kiraveradi).
      * IP noma'lum (`ip_address` yo'q) — eski qoida: login bo'yicha 5.
    Hodim kirishi (telefon raqami kaliti) — xuddi shu qoida.

    kech199 (zip 263, xavfsizlik REJA 17-band — Fable F12): IP chegarasi 20 → 60. Uyali operatorlar minglab abonentni bitta umumiy
    manzil (CGNAT) ortida chiqaradi — 20 ta begona xato shu manzildagi HAMMA foydalanuvchi va hodimni 15 daqiqa kiritmasdi. Asosiy himoya —
    (login, IP) juftligi (5) va login bo'yicha jami (30) — o'zgarmagan; IP chegarasi faqat bitta manzildan ko'p hisoblarni terishga qarshi.
    kech199 (zip 263, 12-band): natijada blok SABABI ham bor (`sabab`: «login_ip» / «ip» / «login_jami» / «login») — platforma egasi
    tarqoq hujumda (`login_jami`) to'g'ri parol + Telegram kodi bilan blokdan o'tadi (`main.login_submit`), egasiga xabar ketadi.

    Qaytaradi: {"blocked": bool, "retry_after_minutes": int, "sabab": str (faqat blokda)}"""
    from models import LoginHistory
    from datetime import timedelta

    cutoff = datetime.utcnow() - timedelta(minutes=window_minutes)

    # M7 — TENANT: nom bo'yicha hisob (company_id, username) juftligi
    # bo'yicha olinadi. Ilgari u global edi: bir korxonada `admin` nomiga
    # 5 marta noto'g'ri urinilsa, BOSHQA korxonaning `admin`i ham bloklanardi
    # (lokal sinovda tasdiqlangan — korxonalararo DoS).
    # IP bo'yicha himoya ATAYLAB global qoladi: bitta IP dan turli
    # korxonalarga urinish ham xuddi shunday hujum.
    # kech146 (zip 183, J1): hodim yo'llari korxonani o'zi beradi (`company_id`) — yozuv bilan BIR xil korxona bo'yicha sanaladi
    _uname_cid = company_id if company_id is not None else (_company_of_username(db, username) if aniqla else None)
    q = db.query(LoginHistory).filter(
        LoginHistory.success == False,
        LoginHistory.created_at >= cutoff
    )
    _uq = q.filter(LoginHistory.username == username)
    if _uname_cid is not None:
        _uq = _uq.filter(LoginHistory.company_id == _uname_cid)
    _blok = {"blocked": True, "retry_after_minutes": window_minutes}
    if not ip_address:
        if _uq.count() >= max_attempts:
            return dict(_blok, sabab="login")
        return {"blocked": False, "retry_after_minutes": 0}
    if _uq.filter(LoginHistory.ip_address == ip_address).count() >= max_attempts:
        return dict(_blok, sabab="login_ip")
    if q.filter(LoginHistory.ip_address == ip_address).count() >= ip_max_attempts:
        return dict(_blok, sabab="ip")
    if _uq.count() >= login_jami_max:
        _tq = db.query(LoginHistory.id).filter(
            LoginHistory.success == True,
            LoginHistory.username == username,
            LoginHistory.ip_address == ip_address,
            LoginHistory.created_at >= datetime.utcnow() - timedelta(days=tanish_kun),
        )
        if _uname_cid is not None:
            _tq = _tq.filter(LoginHistory.company_id == _uname_cid)
        if _tq.first() is None:
            return dict(_blok, sabab="login_jami")
    return {"blocked": False, "retry_after_minutes": 0}


def get_login_history(db: Session, limit: int = 100, company_id: int = None) -> List:
    """So'nggi kirish urinishlari (M7 — tenant-safe)."""
    from models import LoginHistory
    q = db.query(LoginHistory)
    if company_id is not None:
        q = q.filter(LoginHistory.company_id == company_id)
    return q.order_by(LoginHistory.created_at.desc()).limit(limit).all()


