SAYT_MAX_JAMI = Decimal("9999999999.99")      # buyurtma summasi ustuni (Numeric(12, 2)) sig'imi
SAYT_TELEFON_SOAT_MAX = 5            # bir telefondan so'nggi 1 soatda ko'pi bilan 5 ta yangi buyurtma
